local EDITABLE_COLORS = {
    { key = "Background",   label = "Background"    },
    { key = "Surface",      label = "Surface"       },
    { key = "SurfaceHover", label = "Surface Hover" },
    { key = "Accent",       label = "Accent"        },
    { key = "Border",       label = "Border"        },
    { key = "TextPrimary",  label = "Text"          },
}

local function DeriveTheme(custom)
    local base = LucidUI.Themes.Default
    local t = {}
    for k, v in pairs(base) do t[k] = v end

    for _, f in ipairs(EDITABLE_COLORS) do
        if custom[f.key] then t[f.key] = custom[f.key] end
    end

    if not custom.SurfaceHover then
        t.SurfaceHover = Color3.new(
            math.min(t.Surface.R + 0.10, 1),
            math.min(t.Surface.G + 0.10, 1),
            math.min(t.Surface.B + 0.10, 1)
        )
    end

    t.TextSecondary = Color3.new(
        math.min(t.TextPrimary.R * 0.92, 1),
        math.min(t.TextPrimary.G * 0.92, 1),
        math.min(t.TextPrimary.B * 0.92, 1)
    )
    t.TextMuted = Color3.new(
        (t.TextPrimary.R + t.Background.R) * 0.5,
        (t.TextPrimary.G + t.Background.G) * 0.5,
        (t.TextPrimary.B + t.Background.B) * 0.5
    )
    t.ToggleOff   = t.Surface
    t.SliderTrack = t.Surface
    t.TabActive   = t.TextPrimary
    t.TabInactive = t.TextMuted
    return t
end

local function NewCustomTheme(fromTheme)
    fromTheme = fromTheme or LucidUI.Themes.Default
    return {
        Background   = fromTheme.Background,
        Surface      = fromTheme.Surface,
        SurfaceHover = fromTheme.SurfaceHover,
        Accent       = fromTheme.Accent,
        Border       = fromTheme.Border,
        TextPrimary  = fromTheme.TextPrimary,
    }
end

-- ============================================================
-- Module: 03_icons.lua
-- ============================================================
--[[
    Icons — frame-based builders. All visuals are constructed from
    Frames/Rects so they render identically on any device.

    BuildGearIcon returns (holder, spinTarget, parts, hole):
      holder     — the 18×18 container parented to the button
      spinTarget — the object whose .Rotation should be animated.
                   This is the HOLDER, not the ring. Rotating the
                   ring alone does nothing visible because a circle
                   looks the same at every angle, and the teeth are
                   siblings of the ring, not children.
      parts      — array of all colored frames (for theme tweens)
      hole       — the center cutout frame
]]

local function IconHolder(parent, size)
    return Create("Frame", {
        Size = UDim2.fromOffset(size, size),
        BackgroundTransparency = 1,
        Parent = parent,
    })
end

-- ============================================================
-- Gear (settings) — 8 rounded teeth + solid ring + center hole
-- ============================================================
function BuildGearIcon(parent, size, color, holeColor)
    size = size or 18

    local holder = IconHolder(parent, size)
    local parts  = {}

    local ringDiameter = size * 0.70
    local ringRadius   = ringDiameter / 2
    local toothLen     = size * 0.22
    local toothWid     = size * 0.20
    local toothDist    = ringRadius + toothLen * 0.15
    local teethCount   = 8

    -- Teeth sit behind the ring so their inner ends tuck under it
    for i = 1, teethCount do
        local angle = (i - 1) * (360 / teethCount)
        local rad   = math.rad(angle - 90)
        local px    = 0.5 + (toothDist / size) * math.cos(rad)
        local py    = 0.5 + (toothDist / size) * math.sin(rad)

        local tooth = Create("Frame", {
            Size             = UDim2.fromOffset(toothWid, toothLen),
            Position         = UDim2.fromScale(px, py),
            AnchorPoint      = Vector2.new(0.5, 0.5),
            Rotation         = angle,
            BackgroundColor3 = color,
            BorderSizePixel  = 0,
            Parent           = holder,
        })
        Corner(toothWid * 0.35, tooth)
        table.insert(parts, tooth)
    end

    -- Main ring on top of teeth
    local ring = Create("Frame", {
        Size             = UDim2.fromOffset(ringDiameter, ringDiameter),
        Position         = UDim2.fromScale(0.5, 0.5),
        AnchorPoint      = Vector2.new(0.5, 0.5),
        BackgroundColor3 = color,
        BorderSizePixel  = 0,
        Parent           = holder,
    })
    Corner(999, ring)
    table.insert(parts, ring)

    -- Center hole
    local holeSize = ringDiameter * 0.36
    local hole = Create("Frame", {
        Size             = UDim2.fromOffset(holeSize, holeSize),
        Position         = UDim2.fromScale(0.5, 0.5),
        AnchorPoint      = Vector2.new(0.5, 0.5),
        BackgroundColor3 = holeColor or Color3.fromRGB(28, 28, 30),
        BorderSizePixel  = 0,
        Parent           = ring,
    })
    Corner(999, hole)

    -- Return the holder as the spin target so the whole gear
    -- (ring + teeth + hole) rotates as one unit.
    return holder, holder, parts, hole
end

-- ============================================================
-- Module: 04_intro.lua
-- ============================================================
--[[
    Intro — premium animated loading screen with task support.

    Visuals:
      • Music-reactive blob behind the card (stretches on the beat)
      • Rotating gradient border on the glass card
      • Geometric logo with an orbiting dot and breathing pulse
      • Version chip pill under the title
      • Stage dots that fill in one by one
      • Progress bar with a UIGradient shimmer
      • Expanding ring + particle burst on completion
      • Staggered entrance for every element
      • Skippable at any moment via click, tap, or keypress

    Blob:
      The blob is a fully procedural bass visualizer. Since Roblox
      has no real-time audio analysis, the "beat" is simulated with
      three layered sine waves (slow bass, kick, snare). The blob
      stretches horizontally and squashes vertically on each pulse,
      sways gently, and fades the shine in/out with the energy.

    Task support:
      Pass opts.Stages = { { text, pct, task?, wait? }, ... }
      Each task function receives a report(subProgress) callback so it
      can advance the bar mid-stage (perfect for downloads).
]]

function LucidUI:ShowIntro(opts)
    opts = opts or {}

    if LucidUI._activeIntro and LucidUI._activeIntro.Parent then
        LucidUI._activeIntro:Destroy()
    end

    local duration     = opts.Duration or 2.8
    local customStages = opts.Stages
    local title        = opts.Title or "LucidUI"
    local subtitle     = opts.Subtitle or ("v" .. LucidUI._version)
    local tagline      = opts.Tagline or "Modern interface suite"
    local theme        = opts.Theme or LucidUI._lastTheme or LucidUI.Themes.Default
    local onComplete   = opts.OnComplete
    local skipOnInput  = opts.SkipOnInput ~= false

    local accent = theme.Accent
    local bg     = theme.Background
    local text   = theme.TextPrimary
    local muted  = theme.TextMuted

    -- Build stage list
    local stages
    if customStages and #customStages > 0 then
        stages = {}
        for _, s in ipairs(customStages) do
            table.insert(stages, {
                text = s.text or "Loading...",
                pct  = s.pct or 1,
                task = s.task,
                wait = s.wait,
            })
        end
    else
        local defaultTexts = {
            "Loading modules...",
            "Initializing theme...",
            "Building interface...",
            "Optimizing layout...",
            "Ready",
        }
        local defaultPcts = { 0.15, 0.38, 0.62, 0.85, 1.00 }
        local perStage = duration / #defaultTexts
        stages = {}
        for i = 1, #defaultTexts do
            table.insert(stages, {
                text = defaultTexts[i],
                pct  = defaultPcts[i],
                wait = perStage,
            })
        end
    end

    local DOT_COUNT = #stages

    -- Root GUI
    local introGui = Create("ScreenGui", {
        Name = "LucidUI_Intro",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 500,
        Parent = PlayerGui,
    })
    LucidUI._activeIntro = introGui

    local overlay = Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Parent = introGui,
