        TextTransparency = 1,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 6,
        Parent = card,
    })

    local rightLbl = Create("TextLabel", {
        Text = "0%",
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = accent,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 28, 1, -52),
        Size = UDim2.new(1, -56, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Right,
        TextTransparency = 1,
        ZIndex = 6,
        Parent = card,
    })

    Tween(overlay, 0.40, { BackgroundTransparency = 0.35 }):Play()
    Tween(blur, 0.55, { Size = 28 }):Play()
    Tween(colorFx, 0.55, { Saturation = -0.25 }):Play()
    Tween(cardScale, 0.55, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
    Tween(card, 0.50, { BackgroundTransparency = theme.BackgroundTrans or 0.15 }):Play()
    Tween(cardStroke, 0.50, { Transparency = 0.35 }):Play()
    Tween(logoLabel, 0.50, { TextTransparency = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
    Tween(orbitDot, 0.50, { BackgroundTransparency = 0 }):Play()

    task.delay(0.25, function() Tween(titleLbl, 0.40, { TextTransparency = 0 }):Play() end)
    task.delay(0.35, function()
        Tween(chip, 0.30, { BackgroundTransparency = 0.85 }):Play()
        Tween(chipStroke, 0.30, { Transparency = 0.40 }):Play()
        Tween(chipLabel, 0.30, { TextTransparency = 0 }):Play()
    end)
    task.delay(0.45, function() Tween(tagLbl, 0.40, { TextTransparency = 0 }):Play() end)
    task.delay(0.55, function()
        for _, d in ipairs(stageDots) do
            Tween(d, 0.30, { BackgroundTransparency = 0.55 }):Play()
        end
        Tween(track, 0.35, { BackgroundTransparency = 0.4 }):Play()
        Tween(statusLbl, 0.30, { TextTransparency = 0 }):Play()
        Tween(rightLbl, 0.30, { TextTransparency = 0 }):Play()
    end)

    local animStart = tick()
    local animConn = RunService.RenderStepped:Connect(function()
        if not introGui.Parent then animConn:Disconnect() return end
        local t = tick() - animStart

        if strokeGrad and strokeGrad.Parent then
            strokeGrad.Rotation = (t * 60) % 360
        end
        if orbitHolder and orbitHolder.Parent then
            orbitHolder.Rotation = (t * 90) % 360
        end
        if logo and logo.Parent then
            logo.BackgroundTransparency = 0.15 + 0.05 * math.sin(t * 3)
        end
        if shimmerGrad and shimmerGrad.Parent then
            local cycle = (t % 1.4) / 1.4
            shimmerGrad.Offset = Vector2.new(-1 + cycle * 2, 0)
        end

        local bass  = (math.sin(t * 0.62) * 0.5) + 0.5
        local kick  = math.max(0, math.sin(t * 2.35)) ^ 4
        local snare = math.max(0, math.sin(t * 3.85 + 1.4)) ^ 6
        local energy = bass * 0.35 + kick * 0.45 + snare * 0.20
        energy = math.clamp(energy, 0, 1)

        local alpha = math.clamp((t - 0.15) / 0.6, 0, 1)

        local stretch = energy * 0.28
        local squash  = energy * 0.10

        local sx = (1 + stretch) * alpha
        local sy = (1 - squash)  * alpha
        blobCore.Size = UDim2.fromScale(sx, sy)

        blobCore.Rotation = math.sin(t * 1.6) * 6 * alpha

        local coreTarget = 0.80 - energy * 0.12
        blobCore.BackgroundTransparency = 1 - (1 - coreTarget) * alpha

        local haloScale = 1.10 + (1 - energy) * 0.15
        blobHalo.Size = UDim2.fromScale(haloScale * alpha, haloScale * alpha)
        local haloTarget = 0.88 - energy * 0.06
        blobHalo.BackgroundTransparency = 1 - (1 - haloTarget) * alpha

        local shineTarget = 0.72 - energy * 0.15
        blobShine.BackgroundTransparency = 1 - (1 - shineTarget) * alpha
    end)

    local function burstParticles()
        for i = 1, 14 do
            local angle = (i / 14) * math.pi * 2
            local dx = math.cos(angle) * 120
            local dy = math.sin(angle) * 120
            local dot = Create("Frame", {
                Size = UDim2.fromOffset(5, 5),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = accent,
                BorderSizePixel = 0,
                ZIndex = 10,
                Parent = overlay,
            })
            Corner(999, dot)
            Tween(dot, 0.7, {
                Position = UDim2.new(0.5, dx, 0.5, dy),
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(2, 2),
            }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
            task.delay(0.8, function() pcall(function() dot:Destroy() end) end)
        end
    end

    local function expandRing()
        local ring = Create("Frame", {
            Size = UDim2.fromOffset(60, 60),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 10,
            Parent = overlay,
        })
        Corner(999, ring)
        local ringStroke = Stroke(accent, 3, 0, ring)
        Tween(ring, 0.7, {
            Size = UDim2.fromOffset(420, 420),
        }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
        Tween(ringStroke, 0.7, {
            Transparency = 1,
            Thickness = 1,
        }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
        task.delay(0.8, function() pcall(function() ring:Destroy() end) end)
    end

    local completed = false
    local function finish()
        if completed then return end
        completed = true

        if animConn then animConn:Disconnect() end

        expandRing()
        burstParticles()

        Tween(card, 0.5, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In):Play()
        Tween(cardStroke, 0.5, { Transparency = 1 }):Play()
        Tween(logo, 0.4, { BackgroundTransparency = 1 }):Play()
        Tween(logoLabel, 0.35, { TextTransparency = 1 }):Play()
        Tween(orbitDot, 0.3, { BackgroundTransparency = 1 }):Play()
        Tween(titleLbl, 0.35, { TextTransparency = 1 }):Play()
        Tween(chip, 0.3, { BackgroundTransparency = 1 }):Play()
        Tween(chipStroke, 0.3, { Transparency = 1 }):Play()
        Tween(chipLabel, 0.3, { TextTransparency = 1 }):Play()
        Tween(tagLbl, 0.35, { TextTransparency = 1 }):Play()
        Tween(track, 0.35, { BackgroundTransparency = 1 }):Play()
        Tween(fill, 0.35, { BackgroundTransparency = 1 }):Play()
        Tween(fillGlow, 0.35, { Transparency = 1 }):Play()
        Tween(statusLbl, 0.3, { TextTransparency = 1 }):Play()
        Tween(rightLbl, 0.3, { TextTransparency = 1 }):Play()
        for _, d in ipairs(stageDots) do
            Tween(d, 0.3, { BackgroundTransparency = 1 }):Play()
        end

        Tween(blobCore, 0.6, {
            Size = UDim2.fromScale(1.6, 1.6),
            BackgroundTransparency = 1,
        }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
        Tween(blobHalo, 0.6, {
            Size = UDim2.fromScale(2.0, 2.0),
            BackgroundTransparency = 1,
        }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out):Play()
        Tween(blobShine, 0.4, { BackgroundTransparency = 1 }):Play()

        Tween(cardScale, 0.55, { Scale = 1.06 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In):Play()
        Tween(overlay, 0.65, { BackgroundTransparency = 1 }):Play()
        Tween(blur, 0.65, { Size = 0 }):Play()
        Tween(colorFx, 0.65, { Saturation = 0, Brightness = 0, Contrast = 0 }):Play()

        task.wait(0.7)

        if blur.Parent then blur:Destroy() end
        if colorFx.Parent then colorFx:Destroy() end
        if introGui.Parent then introGui:Destroy() end
        if LucidUI._activeIntro == introGui then LucidUI._activeIntro = nil end

        if onComplete then pcall(onComplete) end
    end

    if skipOnInput then
        local skipConn
        skipConn = UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
                or input.UserInputType == Enum.UserInputType.Keyboard then
                if skipConn then skipConn:Disconnect() end
                finish()
            end
        end)
        task.delay(duration + 5, function()
            if skipConn then skipConn:Disconnect() end
        end)
    end

    task.spawn(function()
        local prevPct = 0

        for index, stage in ipairs(stages) do
            if completed then return end

            statusLbl.Text = stage.text
            rightLbl.Text = string.format("%d%%", math.floor(stage.pct * 100))

            local dot = stageDots[index]
            if dot then
                Tween(dot, 0.25, { BackgroundColor3 = accent, BackgroundTransparency = 0 }):Play()
            end

            if stage.task then
                local startPct = prevPct
                local targetPct = stage.pct

                local function report(subProgress)
                    subProgress = math.clamp(subProgress or 0, 0, 1)
                    local pct = startPct + (targetPct - startPct) * subProgress
                    fill.Size = UDim2.new(pct, 0, 1, 0)
                    rightLbl.Text = string.format("%d%%", math.floor(pct * 100))
                end

                local ok, err = pcall(stage.task, report)
                if not ok then
                    warn("[LucidUI] Intro stage task failed:", err)
                end

                Tween(fill, 0.18, {
                    Size = UDim2.new(targetPct, 0, 1, 0),
                }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out):Play()
                rightLbl.Text = string.format("%d%%", math.floor(targetPct * 100))
                task.wait(0.15)

            else
                local waitTime  = stage.wait or 0.35
                local startPct  = prevPct
                local targetPct = stage.pct

                Tween(fill, waitTime, {
                    Size = UDim2.new(targetPct, 0, 1, 0),
                }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out):Play()
                Tween(fillGlow, waitTime, { Transparency = 0.35 }):Play()

                local elapsed = 0
                local step = 0.05
                while elapsed < waitTime do
                    if completed then return end
                    local sub = elapsed / waitTime
                    local pct = startPct + (targetPct - startPct) * sub
                    rightLbl.Text = string.format("%d%%", math.floor(pct * 100))
                    task.wait(step)
                    elapsed = elapsed + step
                end
            end

            prevPct = stage.pct
        end

        task.wait(0.25)
        finish()
    end)

    return introGui
end

-- ============================================================
-- Module: 05_notifications.lua
-- ============================================================
--[[
    Notifications — glass toasts in the top-right corner.

    Each toast:
      • Slides in from the right with Back easing
      • Has a colored accent bar on the left that adapts to text height
      • Auto-dismisses after Duration (default 4s)
      • Fades out and destroys itself cleanly
]]

-- ============================================================
-- Root container (created once, reused forever)
-- ============================================================
local function GetNotificationRoot()
    if LucidUI._notifRoot and LucidUI._notifRoot.Parent then
        return LucidUI._notifRoot
    end

    local root = Create("ScreenGui", {
        Name = "LucidUI_Notifications",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 200,
        Parent = PlayerGui,
    })

    Create("UIListLayout", {
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        HorizontalAlignment = Enum.HorizontalAlignment.Right,
        Parent = root,
    })

    Create("UIPadding", {
        PaddingTop = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),
        Parent = root,
    })

    LucidUI._notifRoot = root
    return root
end

-- ============================================================
-- Public API
-- ============================================================
function LucidUI:Notify(config)
    config = config or {}

    local theme    = config.Theme or LucidUI._lastTheme or LucidUI.Themes.Default
    local root     = GetNotificationRoot()
    local title    = config.Title or "Notice"
    local message  = config.Message or ""
    local duration = config.Duration or 4
    local accent   = config.Accent or theme.Accent

    -- --------------------------------------------------------
    -- Card
    -- --------------------------------------------------------
    local card = Create("Frame", {
        Size = UDim2.fromOffset(300, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = theme.Background,
        BackgroundTransparency = 1,
        Parent = root,
    })
    Corner(14, card)
    local stroke = Stroke(accent, 1, 0.4, card)

    -- --------------------------------------------------------
    -- Accent bar (height adjusted after layout settles)
    -- --------------------------------------------------------
    local bar = Create("Frame", {
        Size = UDim2.new(0, 3, 0, 20),
        Position = UDim2.fromOffset(8, 10),
        BackgroundColor3 = accent,
        BorderSizePixel = 0,
        Parent = card,
    })
    Corner(2, bar)

    -- --------------------------------------------------------
    -- Title + message
    -- --------------------------------------------------------
    local titleLbl = Create("TextLabel", {
        Text = title,
        Font = Enum.Font.GothamBold,
        TextSize = 14,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(18, 10),
        Size = UDim2.new(1, -30, 0, 18),
        Parent = card,
    })

    local msgLbl = Create("TextLabel", {
        Text = message,
        Font = Enum.Font.Gotham,
        TextSize = 12,
        TextColor3 = theme.TextSecondary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,
        Position = UDim2.fromOffset(18, 30),
        Size = UDim2.new(1, -30, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Parent = card,
    })

    -- Bottom spacer so the card has symmetric padding
    Create("Frame", {
        Size = UDim2.new(1, 0, 0, 10),
        Position = UDim2.new(0, 0, 1, 0),
        BackgroundTransparency = 1,
        Parent = card,
    })

    -- --------------------------------------------------------
    -- Adapt accent bar to message height
    -- --------------------------------------------------------
    task.spawn(function()
        for _ = 1, 20 do
            if not card.Parent then return end
            bar.Size = UDim2.new(0, 3, 0, 18 + 2 + msgLbl.AbsoluteSize.Y)
            task.wait(0.1)
        end
    end)

    -- --------------------------------------------------------
    -- Slide in from the right
    -- --------------------------------------------------------
    card.Position = UDim2.fromOffset(340, 0)
    Tween(card, 0.30, {
        Position = UDim2.fromOffset(0, 0),
        BackgroundTransparency = theme.BackgroundTrans or 0.15,
    }, Enum.EasingStyle.Back):Play()

    -- --------------------------------------------------------
    -- Auto-dismiss
    -- --------------------------------------------------------
    task.delay(duration, function()
        if not card.Parent then return end

        Tween(card, 0.25, {
            Position = UDim2.fromOffset(340, 0),
            BackgroundTransparency = 1,
        }, Enum.EasingStyle.Quad, Enum.EasingDirection.In):Play()

        Tween(stroke,   0.25, { Transparency = 1 }):Play()
        Tween(titleLbl, 0.20, { TextTransparency = 1 }):Play()
        Tween(msgLbl,   0.20, { TextTransparency = 1 }):Play()
        Tween(bar,      0.25, { BackgroundTransparency = 1 }):Play()

        task.wait(0.30)
        if card.Parent then card:Destroy() end
    end)

    return card
end

-- ============================================================
-- Module: 06_window.lua
-- ============================================================
--[[
    Window — creates the main window and every layer that sits inside it.

    Gesture handling:
      Header drag and resize share a single gesture lock (`gesture`).
      Whichever fires InputBegan first owns the gesture; any other
      input object is ignored.

    Click handling:
      Every actual click goes through BindTap (from 01b_polish.lua).

    Keybinds:
      RightShift toggles window visibility.
      W.PillKeybind (configurable, default Home) toggles pill mode.

    Minimize behavior:
      Clicking the orange dot fades out the gear icon, then shrinks
      the window's width to just fit the title.

    Pill:
      Auto-sizes to the hub name (clamped 120–280 px). Blinks a soft
      pulse on the accent dot. Text truncates with ellipsis if the
      name is somehow longer than the max width.
]]

LucidUI.Window = {}
LucidUI.Window.__index = LucidUI.Window

local function TweenColor(inst, prop, target, time)
    local current = inst[prop]
    if typeof(current) ~= "Color3" then
        inst[prop] = target
        return
    end
    TweenService:Create(
        inst,
        TweenInfo.new(time or 0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        { [prop] = target }
    ):Play()
end

local function isPrimaryPointer(input)
    return input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch
end

function LucidUI:CreateWindow(config)
    config = config or {}

    local W = setmetatable({}, LucidUI.Window)

    W.Name         = config.Name or "LucidUI"
    W.Theme        = LucidUI.Themes[config.Theme or "Default"] or LucidUI.Themes.Default
    W.ThemeName    = config.Theme or "Default"
    W.Tabs         = {}
    W.ActiveTab    = nil
    W.Visible      = true
    W.Minimized    = false
    W.Floating     = false
    W.SettingsOpen = false

    W.PillKeybind  = config.PillKeybind or Enum.KeyCode.Home

    W._configData     = {}
    W._elementsByFlag = {}
    W._themeElements  = {}
    W._conns          = {}
    W._accentOverride = nil

    W._minWidth,  W._minHeight = 320, 240
    W._maxWidth,  W._maxHeight = 1200, 900

    W._customTheme       = nil
    W._customThemeActive = false
    W._currentConfig     = "default"
    W._backgroundUrl     = nil

    W._width  = config.Width  or 620
    W._height = config.Height or 460
    W._fullSize      = UDim2.fromOffset(W._width, W._height)
    W._collapsedSize = UDim2.fromOffset(W._width, 44)

    W._compactWidth = nil

    LucidUI._lastTheme = W.Theme
    Compat.ensureFolders()

    W.Gui = Create("ScreenGui", {
        Name = "LucidUI_" .. W.Name,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 100,
        Enabled = false,
        Parent = PlayerGui,
    })

    W.UIScale = Create("UIScale", { Scale = GetResponsiveScale(), Parent = W.Gui })

    table.insert(W._conns, Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
        if W.UIScale and W.UIScale.Parent then W.UIScale.Scale = GetResponsiveScale() end
        pcall(function() ClampPosition(W.Main) end)
        pcall(function() ClampPosition(W.FloatingPill) end)
    end))

    W.Main = Create("Frame", {
        Name = "Main",
        Size = W._fullSize,
        Position = UDim2.new(0.5, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Visible = false,
        Parent = W.Gui,
    })
    ApplyGlass(W.Main, W.Theme, { cornerRadius = 18 })

    W._bgImage = Create("ImageLabel", {
        Name = "BackgroundImage",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Image = "",
        ImageTransparency = 1,
        ScaleType = Enum.ScaleType.Crop,
        ZIndex = 0,
        Visible = false,
        Parent = W.Main,
    })
    Corner(18, W._bgImage)

    W.Header = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 44),
        BackgroundTransparency = 1,
        ZIndex = 3,
        Parent = W.Main,
    })

    W.TitleLabel = Create("TextLabel", {
        Text = W.Name,
        Font = Enum.Font.GothamBold,
        TextSize = 16,
        TextColor3 = W.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(18, 0),
        Size = UDim2.new(1, -170, 1, 0),
        ZIndex = 3,
        Parent = W.Header,
    })

    -- Compact width for the minimized title bar
    local titlePx = TextService:GetTextSize(
        W.Name, 16, Enum.Font.GothamBold, Vector2.new(2000, 44)
    )
    W._compactWidth = math.clamp(titlePx.X + 120, 220, W._width)

    -- Pill width: measures the pill label (13px GothamBold), pads
    -- by 50 px for the accent dot and margins, clamped 120–280.
    local pillTextPx = TextService:GetTextSize(
        W.Name, 13, Enum.Font.GothamBold, Vector2.new(2000, 32)
    )
    local pillWidth = math.clamp(pillTextPx.X + 50, 120, 280)

    local settingsBtn = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(36, 36),
        Position = UDim2.new(1, -120, 0.5, -18),
        ZIndex = 3,
        Parent = W.Header,
    })
    W._settingsBtn = settingsBtn

    local gearHolder, gearRing, gearParts, gearHole =
        BuildGearIcon(settingsBtn, 18, W.Theme.TextSecondary, W.Theme.Background)
    gearHolder.Position = UDim2.fromScale(0.5, 0.5)
    gearHolder.AnchorPoint = Vector2.new(0.5, 0.5)

    local gearRot   = 0
    local gearSpeed = 30
    table.insert(W._conns, RunService.RenderStepped:Connect(function(dt)
        if not gearRing or not gearRing.Parent then return end
        gearRot = (gearRot + dt * gearSpeed) % 360
        gearRing.Rotation = gearRot
    end))

    BindTap(settingsBtn, function() W:ToggleSettings() end)

    settingsBtn.MouseEnter:Connect(function()
        for _, p in ipairs(gearParts) do
            Tween(p, 0.15, { BackgroundColor3 = W.Theme.Accent }):Play()
        end
        gearSpeed = 120
    end)
    settingsBtn.MouseLeave:Connect(function()
        for _, p in ipairs(gearParts) do
            Tween(p, 0.15, { BackgroundColor3 = W.Theme.TextSecondary }):Play()
        end
        gearSpeed = 30
    end)

    W._gearRefs = { parts = gearParts, hole = gearHole, ring = gearRing }

    local minBtn = Create("TextButton", {
        Text = "",
        BackgroundColor3 = Color3.fromRGB(255, 189, 46),
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(12, 12),
        Position = UDim2.new(1, -48, 0.5, -6),
        AutoButtonColor = false,
        ZIndex = 3,
        Parent = W.Header,
    })
    Corner(999, minBtn)

    local minDot = Create("TextLabel", {
        Text = "-",
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(140, 90, 0),
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        TextTransparency = 1,
        ZIndex = 4,
        Parent = minBtn,
    })

    BindTap(minBtn, function() W:SetMinimized(not W.Minimized) end, { MoveThreshold = 8 })

    minBtn.MouseEnter:Connect(function()
        Tween(minBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 214, 100) }):Play()
        Tween(minDot, 0.15, { TextTransparency = 0 }):Play()
    end)
    minBtn.MouseLeave:Connect(function()
        Tween(minBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 189, 46) }):Play()
        Tween(minDot, 0.15, { TextTransparency = 1 }):Play()
    end)

    local closeBtn = Create("TextButton", {
        Text = "",
        BackgroundColor3 = Color3.fromRGB(255, 95, 87),
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(12, 12),
        Position = UDim2.new(1, -26, 0.5, -6),
        AutoButtonColor = false,
        ZIndex = 3,
        Parent = W.Header,
    })
    Corner(999, closeBtn)

    local closeDot = Create("TextLabel", {
        Text = "x",
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(120, 20, 20),
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        TextTransparency = 1,
        ZIndex = 4,
        Parent = closeBtn,
    })

    BindTap(closeBtn, function() W:MinimizeToPill() end, { MoveThreshold = 8 })

    closeBtn.MouseEnter:Connect(function()
        Tween(closeBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 130, 120) }):Play()
        Tween(closeDot, 0.15, { TextTransparency = 0 }):Play()
    end)
    closeBtn.MouseLeave:Connect(function()
        Tween(closeBtn, 0.15, { BackgroundColor3 = Color3.fromRGB(255, 95, 87) }):Play()
        Tween(closeDot, 0.15, { TextTransparency = 1 }):Play()
    end)

    W._iconRefs = {
        minimize = { label = minBtn },
        close    = { label = closeBtn },
    }

    W.Separator = Create("Frame", {
        Size = UDim2.new(1, -32, 0, 1),
        Position = UDim2.fromOffset(16, 44),
        BackgroundColor3 = W.Theme.Border,
        BackgroundTransparency = W.Theme.BorderTrans + 0.03,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = W.Main,
    })

    W.TabStrip = Create("ScrollingFrame", {
        Name = "TabStrip",
        Size = UDim2.new(1, -32, 0, 34),
        Position = UDim2.fromOffset(16, 52),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.X,
        CanvasSize = UDim2.new(0, 0, 0, 34),
        AutomaticCanvasSize = Enum.AutomaticSize.X,
        ZIndex = 2,
        Parent = W.Main,
    })
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Parent = W.TabStrip,
    })

    W.Content = Create("Frame", {
        Name = "Content",
        Size = UDim2.new(1, -24, 1, -110),
        Position = UDim2.fromOffset(12, 94),
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        ZIndex = 2,
        Parent = W.Main,
    })

    -- ============================================================
    -- Shared gesture state — header drag and resize
    -- ============================================================
    local gesture = {
        input        = nil,
        mode         = nil,
        startPos     = nil,
        startSize    = nil,
        mainStartPos = nil,
    }

    W.Header.InputBegan:Connect(function(input)
    if not isPrimaryPointer(input) then return end
    if gesture.input then return end
    if W._onBeforeDragStart then W:_onBeforeDragStart() end
    gesture.input        = input
    gesture.mode         = "drag"
    gesture.startPos     = input.Position
    gesture.mainStartPos = W.Main.Position
end)

    local resizeHandle = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(20, 20),
        Position = UDim2.new(1, -20, 1, -20),
        ZIndex = 4,
        Parent = W.Main,
    })

    local grip1 = Create("Frame", {
        Size = UDim2.fromOffset(12, 2),
        Position = UDim2.new(1, -6, 1, -6),
        AnchorPoint = Vector2.new(1, 0.5),
        Rotation = 45,
        BackgroundColor3 = W.Theme.TextMuted,
        BackgroundTransparency = 0.5,
        BorderSizePixel = 0,
        Parent = resizeHandle,
    })
    Corner(1, grip1)

    local grip2 = Create("Frame", {
        Size = UDim2.fromOffset(8, 2),
        Position = UDim2.new(1, -6, 1, -3),
        AnchorPoint = Vector2.new(1, 0.5),
        Rotation = 45,
        BackgroundColor3 = W.Theme.TextMuted,
        BackgroundTransparency = 0.5,
        BorderSizePixel = 0,
        Parent = resizeHandle,
    })
    Corner(1, grip2)

    W._gripFrames = { grip1, grip2 }

resizeHandle.InputBegan:Connect(function(input)
    if not isPrimaryPointer(input) then return end
    if gesture.input then return end
    if W._docked then return end
    gesture.input     = input
    gesture.mode      = "resize"

    table.insert(W._conns, UserInputService.InputChanged:Connect(function(input)
        if input ~= gesture.input then return end

        if gesture.mode == "drag" then
           local d = input.Position - gesture.startPos
           W.Main.Position = UDim2.new(
              gesture.mainStartPos.X.Scale, gesture.mainStartPos.X.Offset + d.X,
              gesture.mainStartPos.Y.Scale, gesture.mainStartPos.Y.Offset + d.Y
    )
    if W._onDragTick then W:_onDragTick() end
elseif gesture.mode == "resize" then
            local d = input.Position - gesture.startPos
            W._width  = math.clamp(gesture.startSize.X + d.X, W._minWidth,  W._maxWidth)
            W._height = math.clamp(gesture.startSize.Y + d.Y, W._minHeight, W._maxHeight)
            W._fullSize      = UDim2.fromOffset(W._width, W._height)
            W._collapsedSize = UDim2.fromOffset(W._width, 44)

            local tpx = TextService:GetTextSize(
                W.Name, 16, Enum.Font.GothamBold, Vector2.new(2000, 44)
            )
            W._compactWidth = math.clamp(tpx.X + 120, 220, W._width)

            if not W.Minimized then
                W.Main.Size    = UDim2.fromOffset(W._width, W._height)
                W.Content.Size = UDim2.new(1, -24, 1, -110)
            end
        end
    end))

table.insert(W._conns, UserInputService.InputEnded:Connect(function(input)
    if input ~= gesture.input then return end
    local wasDrag = (gesture.mode == "drag")
    if gesture.mode == "drag" or gesture.mode == "resize" then
        ClampPosition(W.Main)
    end
    if wasDrag and W._onDragEnd then W:_onDragEnd() end
    gesture.input        = nil
    gesture.mode         = nil
    gesture.startPos     = nil
    gesture.startSize    = nil
    gesture.mainStartPos = nil
end))
    
    -- ============================================================
    -- Global keybinds
    -- ============================================================
    table.insert(W._conns, UserInputService.InputBegan:Connect(function(input, processed)
        if processed then return end
        if LucidUI._keyListening then return end

        if input.KeyCode == Enum.KeyCode.RightShift then
            if W.Floating then
                W:RestoreFromPill()
            else
                W:SetVisible(not W.Visible)
            end
        elseif W.PillKeybind and input.KeyCode == W.PillKeybind then
            W:TogglePillMode()
        end
    end))

    -- ============================================================
    -- Settings panel
    -- ============================================================
    W.SettingsPanel = Create("CanvasGroup", {
        Name = "SettingsPanel",
        Size = UDim2.new(1, 0, 1, -45),
        Position = UDim2.new(0, 0, 0, 45),
        BackgroundColor3 = W.Theme.Background,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        Visible = false,
        GroupTransparency = 1,
        ZIndex = 5,
        Parent = W.Main,
    })
    local spCorner = Instance.new("UICorner")
    spCorner.TopLeftRadius     = UDim.new(0, 0)
    spCorner.TopRightRadius    = UDim.new(0, 0)
    spCorner.BottomLeftRadius  = UDim.new(0, 18)
    spCorner.BottomRightRadius = UDim.new(0, 18)
    spCorner.Parent = W.SettingsPanel

    local spHeader = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 40),
        BackgroundTransparency = 1,
        ZIndex = 6,
        Parent = W.SettingsPanel,
    })

    local backBtn = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(32, 32),
        Position = UDim2.fromOffset(12, 4),
        ZIndex = 7,
        Parent = spHeader,
    })
    local backLbl = Create("TextLabel", {
        Text = "<",
        Font = Enum.Font.GothamBold,
        TextSize = 22,
        TextColor3 = W.Theme.TextSecondary,
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 7,
        Parent = backBtn,
    })

    BindTap(backBtn, function()
        if W._cancelKeybindListen then pcall(W._cancelKeybindListen) end
        W:ToggleSettings(false)
    end, { MoveThreshold = 8 })

    Create("TextLabel", {
        Text = "Settings",
        Font = Enum.Font.GothamBold,
        TextSize = 16,
        TextColor3 = W.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(52, 0),
        Size = UDim2.new(1, -60, 1, 0),
        ZIndex = 7,
        Parent = spHeader,
    })

    Create("Frame", {
        Size = UDim2.new(1, -24, 0, 1),
        Position = UDim2.fromOffset(12, 40),
        BackgroundColor3 = W.Theme.Border,
        BackgroundTransparency = W.Theme.BorderTrans + 0.03,
        BorderSizePixel = 0,
        ZIndex = 7,
        Parent = W.SettingsPanel,
    })

    local spContent = Create("ScrollingFrame", {
        Size = UDim2.new(1, -20, 1, -50),
        Position = UDim2.fromOffset(10, 44),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = W.Theme.TextMuted,
        ScrollBarImageTransparency = 0.5,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ZIndex = 6,
        Parent = W.SettingsPanel,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = spContent,
    })
    Create("UIPadding", {
        PaddingRight = UDim.new(0, 8),
        PaddingBottom = UDim.new(0, 12),
        Parent = spContent,
    })

    W._spContent     = spContent
    W._settingsOrder = 0
    W._backArrowLbl  = backLbl

    -- ============================================================
    -- Floating pill — auto-sized, clipped, blinking dot
    -- ============================================================
    W.FloatingPill = Create("TextButton", {
        Name = "FloatingPill",
        Text = "",
        Size = UDim2.fromOffset(pillWidth, 32),
        Position = UDim2.new(0.5, 0, 0, 8),
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundColor3 = W.Theme.Background,
        BackgroundTransparency = W.Theme.BackgroundTrans,
        AutoButtonColor = false,
        Visible = false,
        ClipsDescendants = true,
        Parent = W.Gui,
    })
    Corner(16, W.FloatingPill)
    W._pillStroke = Stroke(W.Theme.Accent, 1, 0.3, W.FloatingPill)

    W._pillDot = Create("Frame", {
        Size = UDim2.fromOffset(8, 8),
        Position = UDim2.fromOffset(14, 12),
        BackgroundColor3 = W.Theme.Accent,
        BorderSizePixel = 0,
        Parent = W.FloatingPill,
    })
    Corner(4, W._pillDot)

    W._pillLabel = Create("TextLabel", {
        Text = W.Name,
        Font = Enum.Font.GothamBold,
        TextSize = 13,
        TextColor3 = W.Theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Position = UDim2.fromOffset(28, 0),
        Size = UDim2.new(1, -34, 1, 0),
        Parent = W.FloatingPill,
    })

    -- Blink loop for the pill dot. Runs forever, does nothing while
    -- the pill is hidden. Reads W._pillDot each tick so it survives
    -- theme rebuilds.
    task.spawn(function()
        local t = 0
        while W._pillDot do
            if W._pillDot.Parent then
                t = (t + 0.03) % 2
                -- Soft pulse: 0 → 0.55 → 0 over 2 s
                local pulse = 0.5 + 0.5 * math.sin(t * math.pi)
                W._pillDot.BackgroundTransparency = pulse * 0.55
            end
            task.wait(0.03)
        end
    end)

    local pillGesture = { input = nil, startPos = nil, startWindowPos = nil }

    W.FloatingPill.InputBegan:Connect(function(input)
        if not isPrimaryPointer(input) then return end
        if pillGesture.input then return end
        pillGesture.input          = input
        pillGesture.startPos       = input.Position
        pillGesture.startWindowPos = W.FloatingPill.Position
    end)

    table.insert(W._conns, UserInputService.InputChanged:Connect(function(input)
        if input ~= pillGesture.input then return end
        local d = input.Position - pillGesture.startPos
        W.FloatingPill.Position = UDim2.new(
            pillGesture.startWindowPos.X.Scale, pillGesture.startWindowPos.X.Offset + d.X,
            pillGesture.startWindowPos.Y.Scale, pillGesture.startWindowPos.Y.Offset + d.Y
        )
    end))

    table.insert(W._conns, UserInputService.InputEnded:Connect(function(input)
        if input ~= pillGesture.input then return end
        ClampPosition(W.FloatingPill)
        pillGesture.input          = nil
        pillGesture.startPos       = nil
        pillGesture.startWindowPos = nil
    end))

    BindTap(W.FloatingPill, function()
        W:RestoreFromPill()
    end, { MoveThreshold = 8 })

    table.insert(LucidUI._windows, W)

    print("[LucidUI] Window created:", W.Name)

    local entranceScale = Create("UIScale", { Scale = 0.90, Parent = W.Main })

    local function RunEntrance()
        W.Main.Visible = true
        W.Gui.Enabled  = true
        entranceScale.Scale = 0.90
        W.Main.BackgroundTransparency = 1
        Tween(entranceScale, 0.40, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out):Play()
        Tween(W.Main, 0.40, { BackgroundTransparency = W.Theme.BackgroundTrans }):Play()
    end

    if W._initDocking then W:_initDocking(config) end
    if config.IntroEnabled ~= false and type(LucidUI.ShowIntro) == "function" then
        LucidUI:ShowIntro({
            Title       = config.IntroTitle or W.Name,
            Subtitle    = config.IntroSubtitle or ("v" .. LucidUI._version),
            Tagline     = config.IntroTagline or "Modern interface suite",
            Duration    = config.IntroDuration or 2.8,
            Stages      = config.IntroStages,
            Theme       = W.Theme,
            SkipOnInput = config.IntroSkipOnInput ~= false,
            OnComplete  = RunEntrance,
        })
    else
        RunEntrance()
    end

    return W
end

function LucidUI.Window:MinimizeToPill()
    if not self.FloatingPill then return end
    self.Floating = true

    local mx, my = self.Main.Position.X, self.Main.Position.Y

    local mainSlide = TweenService:Create(self.Main, Ease.In(0.22), {
        Position = UDim2.new(mx.Scale, mx.Offset, my.Scale, my.Offset - 30),
        BackgroundTransparency = 1,
    })
    mainSlide:Play()

    mainSlide.Completed:Connect(function()
        if not self.Floating then return end

        self.Main.Visible  = false
        self.Main.Position = UDim2.new(0.5, 0, 0.5, 0)

        self.FloatingPill.Visible                = true
        self.FloatingPill.Position               = UDim2.new(0.5, 0, 0, -50)
        self.FloatingPill.BackgroundTransparency = 1
        self._pillStroke.Transparency            = 1
        self._pillDot.BackgroundTransparency     = 1
        self._pillLabel.TextTransparency         = 1

        TweenService:Create(self.FloatingPill, Ease.Out(0.32), {
            Position = UDim2.new(0.5, 0, 0, 8),
        }):Play()
        TweenService:Create(self.FloatingPill, Ease.FadeIn(0.25), {
            BackgroundTransparency = self.Theme.BackgroundTrans,
        }):Play()
        TweenService:Create(self._pillStroke, Ease.FadeIn(0.28), { Transparency = 0.3 }):Play()
        TweenService:Create(self._pillLabel,  Ease.FadeIn(0.25), { TextTransparency = 0 }):Play()
        -- Dot is handled by the blink loop, but start it fully visible
        -- so the fade-in doesn't fight the pulse.
        self._pillDot.BackgroundTransparency = 0
    end)
end

function LucidUI.Window:RestoreFromPill()
    if not self.FloatingPill then return end
    self.Floating = false

    local slide = TweenService:Create(self.FloatingPill, Ease.In(0.26), {
        Position = UDim2.new(0.5, 0, 0, -50),
    })
    slide:Play()

    TweenService:Create(self.FloatingPill, Ease.FadeOut(0.20), { BackgroundTransparency = 1 }):Play()
    TweenService:Create(self._pillStroke,  Ease.FadeOut(0.20), { Transparency = 1 }):Play()
    TweenService:Create(self._pillDot,     Ease.FadeOut(0.18), { BackgroundTransparency = 1 }):Play()
    TweenService:Create(self._pillLabel,   Ease.FadeOut(0.18), { TextTransparency = 1 }):Play()

    self.Main.Visible                = true
    self.Main.Position               = UDim2.new(0.5, 0, 0.5, -20)
    self.Main.BackgroundTransparency = 1

    TweenService:Create(self.Main, Ease.Out(0.35), {
        Position = UDim2.new(0.5, 0, 0.5, 0),
        BackgroundTransparency = self.Theme.BackgroundTrans,
    }):Play()

    slide.Completed:Connect(function()
        if not self.Floating then
            self.FloatingPill.Visible = false
        end
    end)

    task.delay(0.4, function() ClampPosition(self.Main) end)
end

function LucidUI.Window:TogglePillMode()
    if self.Floating then
        self:RestoreFromPill()
    else
        self:MinimizeToPill()
    end
end

function LucidUI.Window:ToggleSettings(state)
    if state == nil then state = not self.SettingsOpen end
    self.SettingsOpen = state

    local SHOWN  = UDim2.new(0, 0, 0, 45)
    local HIDDEN = UDim2.new(0, 0, 0, 85)

    if state then
        self.TabStrip.Visible  = false
        self.Content.Visible   = false
        self.Separator.Visible = false

        self.SettingsPanel.Visible           = true
        self.SettingsPanel.Position          = HIDDEN
        self.SettingsPanel.GroupTransparency = 1

        TweenService:Create(self.SettingsPanel, Ease.Out(0.38), { Position = SHOWN }):Play()
        TweenService:Create(self.SettingsPanel, Ease.FadeIn(0.32), { GroupTransparency = 0 }):Play()

        if self._themeSlotsRefresh    then pcall(self._themeSlotsRefresh) end
        if self._themeDropdownRefresh then pcall(self._themeDropdownRefresh) end
    else
        if self._cancelKeybindListen then pcall(self._cancelKeybindListen) end

        local slide = TweenService:Create(self.SettingsPanel, Ease.In(0.26), { Position = HIDDEN })
        slide:Play()
        TweenService:Create(self.SettingsPanel, Ease.FadeOut(0.22), { GroupTransparency = 1 }):Play()

        slide.Completed:Connect(function()
            if not self.SettingsOpen then
                self.SettingsPanel.Visible = false
                if not self.Minimized then
                    self.TabStrip.Visible  = true
                    self.Content.Visible   = true
                    self.Separator.Visible = true
                end
            end
        end)
    end
end

function LucidUI.Window:Destroy()
    for _, c in ipairs(self._conns or {}) do
        if typeof(c) == "RBXScriptConnection" then c:Disconnect() end
    end
    self._conns = {}

    if LucidUI._activeSlider and LucidUI._activeSlider.Parent == self.Gui then
        LucidUI._activeSlider = nil
    end

    if self.Gui then
        self.Gui:Destroy()
        self.Gui = nil
    end

    for i, w in ipairs(LucidUI._windows) do
        if w == self then
            table.remove(LucidUI._windows, i)
            break
        end
    end

    print("[LucidUI] Window destroyed:", self.Name)
end

function LucidUI.Window:SetVisible(state)
    self.Visible = state
    if self.Gui then self.Gui.Enabled = state end
end

function LucidUI.Window:SetMinimized(state)
    if state == self.Minimized then return end
    self.Minimized = state

    local collapsedHeight = 44
    local targetWidth  = state and (self._compactWidth or self._width) or self._width
    local targetHeight = state and collapsedHeight or self._height

    if state then
        if self._gearRefs then
            for _, p in ipairs(self._gearRefs.parts) do
                TweenService:Create(p, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    { BackgroundTransparency = 1 }):Play()
            end
            if self._gearRefs.hole then
                TweenService:Create(self._gearRefs.hole, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                    { BackgroundTransparency = 1 }):Play()
            end
        end
        task.delay(0.17, function()
            if self._settingsBtn then
                self._settingsBtn.Visible = false
            end
        end)

        if self.SettingsOpen then self:ToggleSettings(false) end

        self.Content.Visible   = false
        self.Separator.Visible = false
        self.TabStrip.Visible  = false
    end

    TweenService:Create(self.Main, Ease.Out(0.30), {
        Size = UDim2.fromOffset(targetWidth, targetHeight),
    }):Play()

    if not state then
        task.delay(0.05, function()
            if self._settingsBtn then
                self._settingsBtn.Visible = true
                if self._gearRefs then
                    for _, p in ipairs(self._gearRefs.parts) do
                        p.BackgroundTransparency = 1
                        TweenService:Create(p, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                            { BackgroundTransparency = 0 }):Play()
                    end
                    if self._gearRefs.hole then
                        self._gearRefs.hole.BackgroundTransparency = 1
                        TweenService:Create(self._gearRefs.hole, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                            { BackgroundTransparency = 0 }):Play()
                    end
                end
            end
        end)

        if not self.SettingsOpen then
            task.delay(0.15, function()
                if not self.Minimized then
                    self.Content.Visible   = true
                    self.Separator.Visible = true
                    self.TabStrip.Visible  = true
                end
            end)
        end
    end

    task.delay(0.35, function() ClampPosition(self.Main) end)
end

function LucidUI.Window:SetTheme(name)
    if name == "Custom" or name == "__custom_runtime" then
        self:ApplyCustomTheme()
        return
    end
    if LucidUI.Themes[name] then
        self.Theme     = LucidUI.Themes[name]
        self.ThemeName = name
        self._customThemeActive = false
        LucidUI._lastTheme = self.Theme
        self:SetThemeObject(self.Theme)
        return
    end
    self:LoadCustomTheme(name)
end

function LucidUI.Window:SetThemeObject(t)
    if not t then return end

    TweenColor(self.Main, "BackgroundColor3", t.Background, 0.30)
    if not (self._bgImage and self._bgImage.Visible) then
        self.Main.BackgroundTransparency = t.BackgroundTrans or 0.20
    end

    TweenColor(self.TitleLabel, "TextColor3", t.TextPrimary, 0.30)
    TweenColor(self.Separator, "BackgroundColor3", t.Border, 0.30)
    TweenColor(self.SettingsPanel, "BackgroundColor3", t.Background, 0.30)

    local accent = self._accentOverride or t.Accent
    if self._pillStroke then self._pillStroke.Color = accent end

    if self.FloatingPill then
        TweenColor(self.FloatingPill, "BackgroundColor3", t.Background, 0.30)
        TweenColor(self._pillLabel, "TextColor3", t.TextPrimary, 0.30)
        TweenColor(self._pillDot, "BackgroundColor3", accent, 0.30)
    end

    if self._gearRefs then
        for _, p in ipairs(self._gearRefs.parts) do
            TweenColor(p, "BackgroundColor3", t.TextSecondary, 0.30)
        end
        TweenColor(self._gearRefs.hole, "BackgroundColor3", t.Background, 0.30)
    end

    if self._backArrowLbl then
        TweenColor(self._backArrowLbl, "TextColor3", t.TextSecondary, 0.30)
    end

    for _, g in ipairs(self._gripFrames or {}) do
        TweenColor(g, "BackgroundColor3", t.TextMuted, 0.30)
    end

    for _, tb in ipairs(self.Tabs) do
        local active = (tb == self.ActiveTab)
        local color  = active and t.TabActive or t.TabInactive
        if tb.Label then TweenColor(tb.Label, "TextColor3", color, 0.30) end
        for _, part in ipairs(tb.IconParts or {}) do
            if part:IsA("UIStroke") then
                part.Color = color
            else
                TweenColor(part, "BackgroundColor3", color, 0.30)
            end
        end
    end

    for _, fn in ipairs(self._themeElements) do
        pcall(fn, t)
    end
end

function LucidUI.Window:SetAccent(c)
    self._accentOverride = c
    self.Theme.Accent    = c

    for _, fn in ipairs(self._themeElements) do pcall(fn, self.Theme) end

    if self._pillStroke then self._pillStroke.Color = c end
    if self._pillDot    then TweenColor(self._pillDot, "BackgroundColor3", c, 0.25) end
end

function LucidUI.Window:_registerTheme(fn)
    table.insert(self._themeElements, fn)
end

-- ============================================================
-- Module: 06b_watermark.lua
-- ============================================================
--[[
    Watermark — a small floating glass pill in a screen corner.

    Shows the hub name plus a live FPS counter. Draggable, theme-aware,
    saves its config. Independent of the main window, so it stays
    visible even when the window is hidden or minimized to pill.

    Setup:
      Window:SetWatermark({
          Text     = "My Hub",      -- defaults to window name
          ShowFPS  = true,
          Position = "top-left",    -- top-left | top-right | bottom-left | bottom-right
          Draggable = true,
          ShowDot  = true,          -- pulsing accent dot
      })

    Methods on the returned object:
      :Set(text)          -- update the main text
      :SetFPS(bool)       -- toggle the FPS readout
      :SetVisible(bool)   -- show / hide the whole pill
      :SetColor(color)    -- override the accent color
      :Destroy()          -- remove completely

    Window-level helpers:
      Window:ToggleWatermark()
      Window:RemoveWatermark()
]]

LucidUI.Watermark = {}
LucidUI.Watermark.__index = LucidUI.Watermark

local WM_POSITIONS = {
    ["top-left"]     = { x = UDim.new(0, 12), y = UDim.new(0, 12), ax = 0, ay = 0 },
    ["top-right"]    = { x = UDim.new(1, -12), y = UDim.new(0, 12), ax = 1, ay = 0 },
    ["bottom-left"]  = { x = UDim.new(0, 12), y = UDim.new(1, -12), ax = 0, ay = 1 },
    ["bottom-right"] = { x = UDim.new(1, -12), y = UDim.new(1, -12), ax = 1, ay = 1 },
}

local function mkCorner(radius, parent)
    return Create("UICorner", { CornerRadius = UDim.new(0, radius), Parent = parent })
end

local function mkStroke(color, thickness, transparency, parent)
    return Create("UIStroke", {
        Color = color,
        Thickness = thickness or 1,
        Transparency = transparency or 0.5,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = parent,
    })
end

function LucidUI.Window:SetWatermark(config)
    config = config or {}

    -- Tear down existing one
    if self._watermark then
        self._watermark:Destroy()
        self._watermark = nil
    end

    local theme = self.Theme
    local W = setmetatable({}, LucidUI.Watermark)
    W.Window = self

    -- Persisted settings
    W._text      = config.Text or self.Name
    W._showFPS   = config.ShowFPS ~= false
    W._showDot   = config.ShowDot ~= false
    W._position  = config.Position or "top-left"
    W._draggable = config.Draggable ~= false
    W._color     = config.Color -- optional override
    W._visible   = true

    -- Independent ScreenGui so the watermark stays on-screen when the
    -- main window is hidden. DisplayOrder sits below notifications
    -- (200) and above the main window (100) so toasts appear on top.
    W.Gui = Create("ScreenGui", {
        Name = "LucidUI_Watermark_" .. self.Name,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
        DisplayOrder = 150,
        Enabled = true,
        Parent = PlayerGui,
    })
    self._watermarkGui = W.Gui

    -- ── Pill ───────────────────────────────────────────────────
    local preset = WM_POSITIONS[W._position] or WM_POSITIONS["top-left"]

    local pill = Create("Frame", {
        Name = "Watermark",
        Size = UDim2.fromOffset(160, 28),
        Position = UDim2.new(preset.x.Scale, preset.x.Offset, preset.y.Scale, preset.y.Offset),
        AnchorPoint = Vector2.new(preset.ax, preset.ay),
        BackgroundColor3 = theme.Background,
        BackgroundTransparency = 0.15,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = W.Gui,
    })
    mkCorner(14, pill)
    local pillStroke = mkStroke(theme.Border, 1, 0.55, pill)
    W.Pill = pill
    W.Stroke = pillStroke

    -- Soft top highlight, matches the glass style used by the window
    local highlight = Create("Frame", {
        Size = UDim2.fromScale(1, 0.5),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0.88,
        BorderSizePixel = 0,
        ZIndex = 3,
        Parent = pill,
    })
    mkCorner(14, highlight)
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Rotation = 90,
        Parent = highlight,
    })
    W.Highlight = highlight

    -- Pulsing accent dot on the left
    local dot
    if W._showDot then
        dot = Create("Frame", {
            Size = UDim2.fromOffset(7, 7),
            Position = UDim2.new(0, 12, 0.5, -3.5),
            BackgroundColor3 = W._color or theme.Accent,
            BorderSizePixel = 0,
            ZIndex = 5,
            Parent = pill,
        })
        mkCorner(999, dot)
        W.Dot = dot
    end

    -- Text: hub name on the left, FPS on the right
    local textX = W._showDot and 26 or 14

    local nameLabel = Create("TextLabel", {
        Text = W._text,
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Position = UDim2.fromOffset(textX, 0),
        Size = UDim2.new(1, -(textX + 60), 1, 0),
        ZIndex = 4,
        Parent = pill,
    })
    W.NameLabel = nameLabel

    local fpsLabel
    if W._showFPS then
        fpsLabel = Create("TextLabel", {
            Text = "60",
            Font = Enum.Font.GothamBold,
            TextSize = 11,
            TextColor3 = theme.TextMuted,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Right,
            Position = UDim2.new(1, -10, 0, 0),
            AnchorPoint = Vector2.new(1, 0),
            Size = UDim2.fromOffset(48, 28),
            ZIndex = 4,
            Parent = pill,
        })
        W.FPSLabel = fpsLabel
    end

    -- Auto-size the pill to the text
    local function resize()
        local namePx = TextService:GetTextSize(
            nameLabel.Text, 12, Enum.Font.GothamBold, Vector2.new(400, 28)
        ).X
        local fpsPx = fpsLabel and TextService:GetTextSize(
            fpsLabel.Text, 11, Enum.Font.GothamBold, Vector2.new(200, 28)
        ).X or 0

        local leftPad  = W._showDot and 26 or 14
        local rightPad = 10
        local gap      = 10

        local total = leftPad + namePx + (fpsPx > 0 and (gap + fpsPx) or 0) + rightPad
        total = math.clamp(total, 100, 320)

        TweenService:Create(pill, TweenInfo.new(0.20, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            { Size = UDim2.fromOffset(total, 28) }):Play()
    end
    resize()
    W._resize = resize

    -- ── FPS counter ────────────────────────────────────────────
    if W._showFPS then
        local frameCount = 0
        local lastUpdate = tick()

        W._fpsConn = RunService.RenderStepped:Connect(function()
            if not pill.Parent then return end
            frameCount = frameCount + 1
            local now = tick()
            if now - lastUpdate >= 0.5 then
                local fps = math.floor(frameCount / (now - lastUpdate) + 0.5)
                frameCount = 0
                lastUpdate = now
                fpsLabel.Text = tostring(fps)

                -- Color shifts: red under 30, yellow 30-55, accent above
                local t = self.Theme
                if fps < 30 then
                    fpsLabel.TextColor3 = Color3.fromRGB(255, 95, 87)
                elseif fps < 55 then
                    fpsLabel.TextColor3 = Color3.fromRGB(255, 189, 46)
                else
                    fpsLabel.TextColor3 = t.TextMuted
                end

                resize()
            end
        end)
    end

    -- ── Dot pulse ──────────────────────────────────────────────
    if W._showDot then
        task.spawn(function()
            while W.Dot and W.Dot.Parent do
                local t = tick()
                local pulse = 0.5 + 0.5 * math.sin(t * 3)
                W.Dot.BackgroundTransparency = pulse * 0.35
                task.wait(0.03)
            end
        end)
    end

    -- ── Drag ───────────────────────────────────────────────────
    if W._draggable then
        local dragging, startPos, startWindowPos, dragInput = false, nil, nil, nil

        pill.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            dragging       = true
            dragInput      = input
            startPos       = input.Position
            startWindowPos = pill.Position
            -- Anchor flips to top-left once dragged so offsets behave
            pill.AnchorPoint = Vector2.new(0, 0)
        end)

        UserInputService.InputChanged:Connect(function(input)
            if not dragging or input ~= dragInput then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            local d = input.Position - startPos
            pill.Position = UDim2.new(
                startWindowPos.X.Scale, startWindowPos.X.Offset + d.X,
                startWindowPos.Y.Scale, startWindowPos.Y.Offset + d.Y
            )
        end)

        UserInputService.InputEnded:Connect(function(input)
            if input ~= dragInput then return end
            dragging  = false
            dragInput = nil

            -- Clamp into the viewport
            local vp   = workspace.CurrentCamera.ViewportSize
            local pos  = pill.AbsolutePosition
            local size = pill.AbsoluteSize
            local nx = math.clamp(pos.X, 0, math.max(vp.X - size.X, 0))
            local ny = math.clamp(pos.Y, 0, math.max(vp.Y - size.Y, 0))
            pill.Position = UDim2.fromOffset(nx, ny)
        end)
    end

    -- ── Theme registration ─────────────────────────────────────
    self:_registerTheme(function(t)
        if not pill.Parent then return end
        pill.BackgroundColor3 = t.Background
        pillStroke.Color      = t.Border
        nameLabel.TextColor3  = t.TextPrimary
        if W.Dot then W.Dot.BackgroundColor3 = W._color or t.Accent end
        if fpsLabel then
            -- Only override if the FPS-tinting logic hasn't set it
            -- to a warn/error color
            if not fpsLabel.TextColor3:match or fpsLabel.Text ~= "60" then
                -- leave as-is, next FPS tick will pick up the right color
            end
        end
    end)

    -- ── Public methods ─────────────────────────────────────────
    function W:Set(text)
        W._text = tostring(text)
        nameLabel.Text = W._text
        W._resize()
    end

    function W:SetFPS(on)
        W._showFPS = on and true or false
        if fpsLabel then
            fpsLabel.Visible = W._showFPS
            W._resize()
        end
    end

    function W:SetVisible(on)
        W._visible = on and true or false
        W.Gui.Enabled = W._visible
    end

    function W:SetColor(c)
        W._color = c
        if W.Dot then W.Dot.BackgroundColor3 = c or self.Theme.Accent end
    end

    function W:Destroy()
        if W._fpsConn then
            pcall(function() W._fpsConn:Disconnect() end)
            W._fpsConn = nil
        end
        if W.Gui then
            W.Gui:Destroy()
            W.Gui = nil
        end
        if self._watermark == W then
            self._watermark = nil
            self._watermarkGui = nil
        end
    end

    -- Persisted config snapshot for save/load
    W._configSnapshot = function()
        return {
            text     = W._text,
            showFPS  = W._showFPS,
            showDot  = W._showDot,
            position = W._position,
            -- Save current position as raw offsets if the user dragged it
            px = pill.Position.X.Scale, py = pill.Position.Y.Scale,
            pxo = pill.Position.X.Offset, pyo = pill.Position.Y.Offset,
            ax = pill.AnchorPoint.X, ay = pill.AnchorPoint.Y,
        }
    end

    function W:RestoreFrom(saved)
        if type(saved) ~= "table" then return end
        if saved.text then W:Set(saved.text) end
        if saved.showFPS ~= nil then W:SetFPS(saved.showFPS) end
        if saved.showDot ~= nil then
            W._showDot = saved.showDot
            if W.Dot then W.Dot.Visible = saved.showDot end
        end
        if saved.px ~= nil then
            pill.Position = UDim2.new(saved.px, saved.pxo or 0, saved.py, saved.pyo or 0)
            pill.AnchorPoint = Vector2.new(saved.ax or 0, saved.ay or 0)
        end
    end

    self._watermark = W
    return W
end

function LucidUI.Window:ToggleWatermark()
    if self._watermark then
        self._watermark:SetVisible(not self._watermark._visible)
    else
        self:SetWatermark({
            Text = self.Name,
            ShowFPS = true,
        })
    end
end

function LucidUI.Window:RemoveWatermark()
    if self._watermark then
        self._watermark:Destroy()
    end
end

-- ============================================================
-- Module: 07_settings_a.lua
-- ============================================================
--[[
    Settings A — theme dropdown, custom theme editor, saved themes.

    Click handling:
      Every click goes through BindTap (from 01b_polish.lua).

    Color picker:
      _openColorPickerModal(opts) is the general-purpose picker.
      Anywhere can call it with { Label, InitialColor, OnChange }.
      The settings Custom Theme editor and the public
      Section:CreateColorPicker element both route through it.

      The modal lives directly under W.Gui (not under the settings
      panel) so it can be opened from anywhere without being clipped
      by the panel's bounds. Its backdrop absorbs every click while
      open, so nothing underneath can be interacted with.

    Auto-contrast:
      ApplyCustomTheme checks the user's TextPrimary against their
      Background using WCAG relative luminance. If the contrast ratio
      is below 4.5:1, it silently swaps to white or near-black.
]]

-- ============================================================
-- Contrast helpers — WCAG relative luminance
-- ============================================================
local function relLuminance(c)
    local function lin(x)
        if x <= 0.03928 then return x / 12.92 end
        return ((x + 0.055) / 1.055) ^ 2.4
    end
    return 0.2126 * lin(c.R) + 0.7152 * lin(c.G) + 0.0722 * lin(c.B)
end

local function contrastRatio(c1, c2)
    local l1, l2 = relLuminance(c1), relLuminance(c2)
    if l1 < l2 then l1, l2 = l2, l1 end
    return (l1 + 0.05) / (l2 + 0.05)
end

local function autoReadableText(preferred, bg, minRatio)
    minRatio = minRatio or 4.5
    if contrastRatio(preferred, bg) >= minRatio then
        return preferred, false
    end
    local light = Color3.fromRGB(240, 240, 245)
    local dark  = Color3.fromRGB(22, 22, 26)
    if contrastRatio(light, bg) >= contrastRatio(dark, bg) then
        return light, true
    else
        return dark, true
    end
end

-- ============================================================
-- Paint bucket icon
-- ============================================================
local function BuildPaintBucketIcon(parent, size, color)
    size = size or 18

    local holder = Create("Frame", {
        Size = UDim2.fromOffset(size, size),
        BackgroundTransparency = 1,
        Parent = parent,
    })

    local barW = math.max(size * 0.08, 1)
    local parts = {}

    local handleH = size * 0.26
    local leftBar = Create("Frame", {
        Size = UDim2.fromOffset(barW, handleH),
        Position = UDim2.new(0.30, 0, 0.12, 0),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(barW / 2, leftBar)
    table.insert(parts, leftBar)

    local rightBar = Create("Frame", {
        Size = UDim2.fromOffset(barW, handleH),
        Position = UDim2.new(0.70, 0, 0.12, 0),
        AnchorPoint = Vector2.new(1, 0),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(barW / 2, rightBar)
    table.insert(parts, rightBar)

    local topBar = Create("Frame", {
        Size = UDim2.fromOffset(size * 0.40, barW),
        Position = UDim2.new(0.50, 0, 0.12, 0),
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(barW / 2, topBar)
    table.insert(parts, topBar)

    local bodyW = size * 0.74
    local bodyH = size * 0.50
    local body = Create("Frame", {
        Size = UDim2.fromOffset(bodyW, bodyH),
        Position = UDim2.new(0.50, 0, 0.62, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    local bodyCorner = Instance.new("UICorner")
    bodyCorner.TopLeftRadius     = UDim.new(0, 1)
    bodyCorner.TopRightRadius    = UDim.new(0, 1)
    bodyCorner.BottomLeftRadius  = UDim.new(0, bodyW * 0.18)
    bodyCorner.BottomRightRadius = UDim.new(0, bodyW * 0.18)
    bodyCorner.Parent = body
    table.insert(parts, body)

    local rim = Create("Frame", {
        Size = UDim2.new(1, 2, 0, barW),
        Position = UDim2.new(0.5, 0, 0, 0),
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundColor3 = color,
        BackgroundTransparency = 0.35,
        BorderSizePixel = 0,
        Parent = body,
    })
    Corner(barW / 2, rim)

    local dropSize = size * 0.16
    local drop = Create("Frame", {
        Size = UDim2.fromOffset(dropSize, dropSize),
        Position = UDim2.new(0.78, 0, 0.94, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = color,
        BorderSizePixel = 0,
        Parent = holder,
    })
    Corner(999, drop)
    table.insert(parts, drop)

    return holder, parts
end

-- ============================================================
-- Setting layout helpers
-- ============================================================
function LucidUI.Window:_addSettingFrame(frame)
    frame.LayoutOrder = self._settingsOrder
    self._settingsOrder = self._settingsOrder + 1
    frame.Parent = self._spContent
    return frame
end

function LucidUI.Window:_addSettingSection(title)
    local label = Create("TextLabel", {
        Text = title:upper(),
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = self.Theme.TextMuted,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, 0, 0, 18),
        LayoutOrder = self._settingsOrder,
        Parent = self._spContent,
    })
    self._settingsOrder = self._settingsOrder + 1
    self:_registerTheme(function(t) label.TextColor3 = t.TextMuted end)
    return label
end

function LucidUI.Window:_ensureCustomTheme()
    if self._customTheme then return end
    self._customTheme = {
        Background   = self.Theme.Background,
        Surface      = self.Theme.Surface,
        SurfaceHover = self.Theme.SurfaceHover,
        Accent       = self.Theme.Accent,
        Border       = self.Theme.Border,
        TextPrimary  = self.Theme.TextPrimary,
    }
end

function LucidUI.Window:ApplyCustomTheme()
    self:_ensureCustomTheme()
    local base = LucidUI.Themes.Default
    local t = {}
    for k, v in pairs(base) do t[k] = v end
    for k, v in pairs(self._customTheme) do t[k] = v end

    local readablePrimary, adjusted = autoReadableText(
        self._customTheme.TextPrimary,
        self._customTheme.Background,
        4.5
    )
    if adjusted then
        self._customTheme.TextPrimary = readablePrimary
    end
    t.TextPrimary = readablePrimary

    t.TextSecondary = Color3.new(
        math.min(t.TextPrimary.R * 0.92, 1),
        math.min(t.TextPrimary.G * 0.92, 1),
        math.min(t.TextPrimary.B * 0.92, 1)
    )

    local mutedRaw = Color3.new(
        (t.TextPrimary.R + t.Background.R) * 0.5,
        (t.TextPrimary.G + t.Background.G) * 0.5,
        (t.TextPrimary.B + t.Background.B) * 0.5
    )
    t.TextMuted = autoReadableText(mutedRaw, t.Background, 3)

    t.ToggleOff   = t.Surface
    t.SliderTrack = t.Surface
    t.TabActive   = t.TextPrimary
    t.TabInactive = t.TextMuted

    LucidUI.Themes["__custom_runtime"] = t
    self.Theme = t
    self.ThemeName = "Custom"
    self._customThemeActive = true
    LucidUI._lastTheme = t
    self:SetThemeObject(t)
end

function LucidUI.Window:SaveCustomTheme(name)
    name = name or "Custom Theme"
    self:_ensureCustomTheme()
    local data = {
        customTheme = Compat.serializeColors(self._customTheme),
        accent = self._accentOverride and {
            R = self._accentOverride.R, G = self._accentOverride.G, B = self._accentOverride.B
        } or nil,
    }
    local encoded = Compat.encode(data)
    if not encoded then return end
    Compat.ensureFolders()
    local ok = Compat.write("LucidUI/Themes/" .. name .. ".json", encoded)
    if ok then
        LucidUI:Notify({ Title = "Theme Saved", Message = name })
        if self._savedThemeSlotsRefresh then pcall(self._savedThemeSlotsRefresh) end
    else
        LucidUI:Notify({ Title = "Save Failed", Message = "No file system", Accent = Color3.fromRGB(255,80,80) })
    end
end

function LucidUI.Window:LoadCustomTheme(name)
    name = name or "Custom Theme"
    local contents = Compat.read("LucidUI/Themes/" .. name .. ".json")
    if not contents then
        LucidUI:Notify({ Title = "Load Failed", Message = "Not found: " .. name, Accent = Color3.fromRGB(255,80,80) })
        return
    end
    local data = Compat.decode(contents)
    if not data or not data.customTheme then return end
    local restored = Compat.deserializeColors(data.customTheme)
    if not restored then return end
    local d = LucidUI.Themes.Default
    self._customTheme = {
        Background   = restored.Background   or d.Background,
        Surface      = restored.Surface      or d.Surface,
        SurfaceHover = restored.SurfaceHover or d.SurfaceHover,
        Accent       = restored.Accent       or d.Accent,
        Border       = restored.Border       or d.Border,
        TextPrimary  = restored.TextPrimary  or d.TextPrimary,
    }
    if data.accent then
        self:SetAccent(Color3.new(data.accent.R, data.accent.G, data.accent.B))
    end
    self:ApplyCustomTheme()
    self.ThemeName = name
    LucidUI:Notify({ Title = "Theme Loaded", Message = name })
end

-- ============================================================
-- General-purpose HSV color picker modal
-- ============================================================
-- Can be called from anywhere. Pass:
--   Label        — header text
--   InitialColor — starting Color3 (defaults to a blue)
--   OnChange     — function(newColor) called live on every change
--   OnClose      — optional, called when the modal is destroyed
function LucidUI.Window:_openColorPickerModal(opts)
    opts = opts or {}
    local initialColor = opts.InitialColor or Color3.fromRGB(90, 180, 255)
    local headerLabel  = opts.Label        or "Color"
    local onChange     = opts.OnChange
    local onClose      = opts.OnClose

    -- One picker per window
    if self._colorPickerModal and self._colorPickerModal.Parent then
        self._colorPickerModal:Destroy()
    end

    local base = initialColor
    local H, S, V = Color3.toHSV(base)

    local modal = Create("Frame", {
        Name = "ColorPickerModal",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.new(0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 500,
        Parent = self.Gui,
    })
    self._colorPickerModal = modal

    local backdrop = Create("TextButton", {
        Name = "Backdrop",
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 1,
        Parent = modal,
    })

    local card = Create("CanvasGroup", {
        Size = UDim2.fromOffset(360, 260),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.05,
        BorderSizePixel = 0,
        GroupTransparency = 1,
        ZIndex = 2,
        Parent = modal,
    })
    Corner(16, card)
    Stroke(self.Theme.Border, 1, 0.5, card)

    local popScale = Instance.new("UIScale")
    popScale.Scale = 0.82
    popScale.Parent = card

    local iconHolder = BuildPaintBucketIcon(card, 20, self.Theme.Accent)
    iconHolder.Position = UDim2.fromOffset(16, 14)
    iconHolder.ZIndex = 3

    Create("TextLabel", {
        Text = headerLabel,
        Font = Enum.Font.GothamBold, TextSize = 15,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(46, 14),
        Size = UDim2.new(1, -60, 0, 22),
        ZIndex = 3, Parent = card,
    })

    local closeBtn = Create("TextButton", {
        Text = "x", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Size = UDim2.fromOffset(28, 28),
        Position = UDim2.new(1, -34, 0, 12),
        ZIndex = 3, Parent = card,
    })

    -- SV square
    local svArea = Create("Frame", {
        Size = UDim2.fromOffset(250, 155),
        Position = UDim2.fromOffset(18, 48),
        BackgroundColor3 = Color3.fromHSV(H, 1, 1),
        BorderSizePixel = 0, ClipsDescendants = true,
        ZIndex = 3, Parent = card,
    })
    Corner(10, svArea)

    local satOverlay = Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, ZIndex = 4, Parent = svArea,
    })
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Rotation = 0, Parent = satOverlay,
    })

    local valOverlay = Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BorderSizePixel = 0, ZIndex = 5, Parent = svArea,
    })
    Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Rotation = 90, Parent = valOverlay,
    })

    local dot = Create("Frame", {
        Size = UDim2.fromOffset(16, 16),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(S, 1 - V),
        BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 2, BorderColor3 = Color3.new(0, 0, 0),
        ZIndex = 6, Parent = svArea,
    })
    Corner(8, dot)

    -- Hue strip
    local hueStrip = Create("Frame", {
        Size = UDim2.fromOffset(26, 155),
        Position = UDim2.new(1, -44, 0, 48),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0, ClipsDescendants = true,
        ZIndex = 3, Parent = card,
    })
    Corner(10, hueStrip)
    Create("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.000, Color3.fromRGB(255, 0, 0)),
            ColorSequenceKeypoint.new(0.167, Color3.fromRGB(255, 255, 0)),
            ColorSequenceKeypoint.new(0.333, Color3.fromRGB(0, 255, 0)),
            ColorSequenceKeypoint.new(0.500, Color3.fromRGB(0, 255, 255)),
            ColorSequenceKeypoint.new(0.667, Color3.fromRGB(0, 0, 255)),
            ColorSequenceKeypoint.new(0.833, Color3.fromRGB(255, 0, 255)),
            ColorSequenceKeypoint.new(1.000, Color3.fromRGB(255, 0, 0)),
        }),
        Rotation = 90, Parent = hueStrip,
    })
    local hueDot = Create("Frame", {
        Size = UDim2.new(1, 0, 0, 5),
        Position = UDim2.new(0, 0, H, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundColor3 = Color3.new(1, 1, 1),
        BorderSizePixel = 1, BorderColor3 = Color3.new(0, 0, 0),
        ZIndex = 6, Parent = hueStrip,
    })

    -- Bottom row
    local preview = Create("Frame", {
        Size = UDim2.fromOffset(32, 32),
        Position = UDim2.fromOffset(18, 214),
        BackgroundColor3 = base,
        BorderSizePixel = 0, ZIndex = 3, Parent = card,
    })
    Corner(8, preview)
    Stroke(self.Theme.Border, 1, 0.5, preview)

    local hexBox = Create("TextBox", {
        Text = string.format("#%02X%02X%02X",
            math.floor(base.R * 255),
            math.floor(base.G * 255),
            math.floor(base.B * 255)),
        Font = Enum.Font.GothamBold, TextSize = 13,
        TextColor3 = self.Theme.TextPrimary,
        BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3,
        ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Center,
        Size = UDim2.fromOffset(120, 32),
        Position = UDim2.fromOffset(60, 214),
        ZIndex = 3, Parent = card,
    })
    Corner(8, hexBox)

    local doneBtn = Create("TextButton", {
        Text = "Done",
        Font = Enum.Font.GothamBold, TextSize = 13,
        TextColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundColor3 = self.Theme.Accent,
        AutoButtonColor = false,
        Size = UDim2.fromOffset(100, 32),
        Position = UDim2.new(1, -118, 0, 214),
        ZIndex = 3, Parent = card,
    })
    Corner(8, doneBtn)

    local function applyColor()
        local c = Color3.fromHSV(H, S, V)
        preview.BackgroundColor3 = c
        svArea.BackgroundColor3  = Color3.fromHSV(H, 1, 1)
        dot.Position             = UDim2.fromScale(S, 1 - V)
        hueDot.Position          = UDim2.new(0, 0, H, 0)
        hexBox.Text = string.format("#%02X%02X%02X",
            math.floor(c.R * 255), math.floor(c.G * 255), math.floor(c.B * 255))
        if onChange then pcall(onChange, c) end
    end

    -- SV drag
    local svDrag = false
    local function svUpdate(input)
        S = math.clamp((input.Position.X - svArea.AbsolutePosition.X) / svArea.AbsoluteSize.X, 0, 1)
        V = 1 - math.clamp((input.Position.Y - svArea.AbsolutePosition.Y) / svArea.AbsoluteSize.Y, 0, 1)
        applyColor()
    end
    svArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            svDrag = true; svUpdate(input)
        end
    end)
    table.insert(self._conns, UserInputService.InputChanged:Connect(function(input)
        if not svDrag then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then svUpdate(input) end
    end))
    table.insert(self._conns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then svDrag = false end
    end))

    -- Hue drag
    local hueDrag = false
    local function hueUpdate(input)
        H = math.clamp((input.Position.Y - hueStrip.AbsolutePosition.Y) / hueStrip.AbsoluteSize.Y, 0, 1)
        applyColor()
    end
    hueStrip.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            hueDrag = true; hueUpdate(input)
        end
    end)
    table.insert(self._conns, UserInputService.InputChanged:Connect(function(input)
        if not hueDrag then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then hueUpdate(input) end
    end))
    table.insert(self._conns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then hueDrag = false end
    end))

    -- Hex input
    hexBox.FocusLost:Connect(function()
        local hex = hexBox.Text:gsub("#", "")
        if #hex == 6 then
            local r = tonumber(hex:sub(1, 2), 16)
            local g = tonumber(hex:sub(3, 4), 16)
            local b = tonumber(hex:sub(5, 6), 16)
            if r and g and b then
                H, S, V = Color3.toHSV(Color3.fromRGB(r, g, b))
                applyColor()
            end
        end
    end)

    -- Pop-in
    TweenService:Create(modal, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        { BackgroundTransparency = 0.55 }):Play()
    TweenService:Create(popScale, TweenInfo.new(0.32, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
        { Scale = 1 }):Play()
    TweenService:Create(card, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        { GroupTransparency = 0 }):Play()

    -- Close
    local closing = false
    local function closeModal()
        if closing then return end
        closing = true

        local exitScale = TweenService:Create(popScale,
            TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            { Scale = 0.86 })
        exitScale:Play()
        TweenService:Create(card, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            { GroupTransparency = 1 }):Play()
        TweenService:Create(modal, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            { BackgroundTransparency = 1 }):Play()

        exitScale.Completed:Connect(function()
            if self._colorPickerModal == modal then
                self._colorPickerModal = nil
            end
            modal:Destroy()
            if onClose then pcall(onClose) end
        end)
    end

    BindTap(backdrop, closeModal)
    BindTap(closeBtn, closeModal)
    BindTap(doneBtn, closeModal)

    -- Return the modal in case the caller wants to track it
    return modal
end

-- Settings-specific wrapper: opens the picker for a Custom Theme field
function LucidUI.Window:_openColorPicker(fieldKey, fieldLabel)
    self:_openColorPickerModal({
        Label = fieldLabel,
        InitialColor = self._customTheme[fieldKey],
        OnChange = function(c)
            self._customTheme[fieldKey] = c
            self:ApplyCustomTheme()
            if self._refreshSwatches then pcall(self._refreshSwatches) end
        end,
    })
end

function LucidUI.Window:_buildThemeSettings()
    self:_addSettingSection("Theme")

    local row = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
        ClipsDescendants = true,
    })
    Corner(10, row)
    local rowStroke = Stroke(self.Theme.Border, 1, self.Theme.BorderTrans + 0.05, row)
    self:_addSettingFrame(row)

    local headerBtn = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 40), Parent = row,
    })
    Create("TextLabel", {
        Text = "Active Theme", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -100, 1, 0), Parent = headerBtn,
    })
    local valueLbl = Create("TextLabel", {
        Text = self.ThemeName, Font = Enum.Font.GothamMedium, TextSize = 13,
        TextColor3 = self.Theme.Accent, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Size = UDim2.new(1, -40, 1, 0), Parent = headerBtn,
    })
    local arrowLbl = Create("TextLabel", {
        Text = "v", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0), Size = UDim2.fromOffset(20, 40), Parent = headerBtn,
    })

    local list = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0), Position = UDim2.fromOffset(10, 40),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = row,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list,
    })

    local expanded = false
    local optionBtns = {}

    local function buildOptions()
        for _, b in ipairs(optionBtns) do b:Destroy() end
        optionBtns = {}

        local options = {}
        local presetNames = {}
        for name in pairs(LucidUI.Themes) do
            if not name:match("^__") and name ~= "Custom" then
                table.insert(presetNames, name)
            end
        end
        table.sort(presetNames, function(a, b)
            if a == "Default" then return true end
            if b == "Default" then return false end
            return a:lower() < b:lower()
        end)
        for _, name in ipairs(presetNames) do table.insert(options, name) end
        table.insert(options, "Custom")
        for _, name in ipairs(Compat.listThemes()) do table.insert(options, name) end

        for i, name in ipairs(options) do
            local opt = Create("TextButton", {
                Text = name, Font = Enum.Font.GothamMedium, TextSize = 13,
                TextColor3 = self.Theme.TextPrimary, BackgroundColor3 = self.Theme.Background,
                BackgroundTransparency = 0.5, AutoButtonColor = false,
                Size = UDim2.new(1, 0, 0, 32), LayoutOrder = i, Parent = list,
            })
            Corner(8, opt)
            opt.MouseEnter:Connect(function()
                local t = self.Theme
                Tween(opt, 0.12, { BackgroundColor3 = t.Accent, BackgroundTransparency = 0.3 }):Play()
            end)
            opt.MouseLeave:Connect(function()
                local t = self.Theme
                Tween(opt, 0.12, { BackgroundColor3 = t.Background, BackgroundTransparency = 0.5 }):Play()
            end)

            local themeName = name
            BindTap(opt, function()
                valueLbl.Text = themeName
                expanded = false
                Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
                Tween(row, 0.22, { Size = UDim2.new(1, 0, 0, 40) }):Play()
                Tween(arrowLbl, 0.2, { Rotation = 0 }):Play()
                if themeName == "Custom" then
                    self:ApplyCustomTheme()
                else
                    self:SetTheme(themeName)
                end
            end)

            table.insert(optionBtns, opt)
        end
    end

    buildOptions()
    self._themeDropdownRefresh = function() if expanded then buildOptions() end end

    BindTap(headerBtn, function()
        expanded = not expanded
        if expanded then buildOptions() end
        local h = #optionBtns * 36 + 8
        Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, expanded and h or 0) }, Enum.EasingStyle.Quart):Play()
        Tween(row, 0.22, { Size = UDim2.new(1, 0, 0, expanded and (40 + h + 8) or 40) }, Enum.EasingStyle.Quart):Play()
        Tween(arrowLbl, 0.2, { Rotation = expanded and 180 or 0 }):Play()
    end)

    self:_registerTheme(function(t)
        row.BackgroundColor3 = t.Surface
        rowStroke.Color = t.Border
        valueLbl.TextColor3 = t.Accent
        arrowLbl.TextColor3 = t.TextMuted
        for _, b in ipairs(optionBtns) do
            b.BackgroundColor3 = t.Background
            b.TextColor3 = t.TextPrimary
        end
    end)
end

function LucidUI.Window:_buildCustomThemeSettings()
    self:_addSettingSection("Custom Theme")
    self:_ensureCustomTheme()

    local fields = {
        { key = "Background",   label = "Background"     },
        { key = "Surface",      label = "Surface"        },
        { key = "SurfaceHover", label = "Surface Hover"  },
        { key = "Accent",       label = "Accent"         },
        { key = "Border",       label = "Border"         },
        { key = "TextPrimary",  label = "Text"           },
    }
    local editorRows = {}
    local swatches   = {}

    for _, field in ipairs(fields) do
        local row = Create("Frame", {
            BackgroundColor3 = self.Theme.Surface,
            BackgroundTransparency = self.Theme.SurfaceTrans,
            Size = UDim2.new(1, 0, 0, 48),
        })
        Corner(10, row)
        self:_addSettingFrame(row)
        table.insert(editorRows, row)

        local labelLbl = Create("TextLabel", {
            Text = field.label,
            Font = Enum.Font.GothamMedium, TextSize = 14,
            TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(14, 0),
            Size = UDim2.new(1, -110, 1, 0),
            Parent = row,
        })

        local swatch = Create("Frame", {
            Size = UDim2.fromOffset(32, 32),
            Position = UDim2.new(1, -46, 0.5, -16),
            BackgroundColor3 = self._customTheme[field.key],
            BorderSizePixel = 0,
            Parent = row,
        })
        Corner(8, swatch)
        Stroke(self.Theme.Border, 1, 0.5, swatch)
        table.insert(swatches, { frame = swatch, key = field.key })

        local clickArea = Create("TextButton", {
            Text = "",
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            ZIndex = 5,
            Parent = row,
        })
        local fieldKey, fieldLabel = field.key, field.label
        BindTap(clickArea, function()
            self:_openColorPicker(fieldKey, fieldLabel)
        end)

        clickArea.MouseEnter:Connect(function()
            local t = self.Theme
            Tween(row, 0.12, {
                BackgroundTransparency = math.max(t.SurfaceTrans - 0.1, 0),
            }):Play()
        end)
        clickArea.MouseLeave:Connect(function()
            local t = self.Theme
            Tween(row, 0.12, { BackgroundTransparency = t.SurfaceTrans }):Play()
        end)
    end

    self._refreshSwatches = function()
        for _, s in ipairs(swatches) do
            s.frame.BackgroundColor3 = self._customTheme[s.key]
        end
    end

    local actionRow = Create("Frame", {
        BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 36),
    })
    self:_addSettingFrame(actionRow)
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6), Parent = actionRow,
    })

    local function mkActionBtn(label, color, cb)
        local b = Create("TextButton", {
            Text = label, Font = Enum.Font.GothamBold, TextSize = 12,
            TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = color,
            BackgroundTransparency = 0.2, AutoButtonColor = false,
            Size = UDim2.new(0.5, -3, 1, 0), Parent = actionRow,
        })
        Corner(8, b)
        BindTap(b, cb, { MoveThreshold = 8 })
        return b
    end

    mkActionBtn("Reset to Default", self.Theme.Surface, function()
        self._customTheme = {
            Background   = LucidUI.Themes.Default.Background,
            Surface      = LucidUI.Themes.Default.Surface,
            SurfaceHover = LucidUI.Themes.Default.SurfaceHover,
            Accent       = LucidUI.Themes.Default.Accent,
            Border       = LucidUI.Themes.Default.Border,
            TextPrimary  = LucidUI.Themes.Default.TextPrimary,
        }
        for _, s in ipairs(swatches) do
            s.frame.BackgroundColor3 = self._customTheme[s.key]
        end
        self:ApplyCustomTheme()
        self._refreshSwatches()
        LucidUI:Notify({ Title = "Reset", Message = "Custom theme reset to Default" })
    end)

    mkActionBtn("Apply Custom", self.Theme.Accent, function()
        self:ApplyCustomTheme()
        self._refreshSwatches()
        LucidUI:Notify({ Title = "Applied", Message = "Custom theme active" })
    end)

    local saveRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
    })
    Corner(10, saveRow)
    self:_addSettingFrame(saveRow)

    local nameBox = Create("TextBox", {
        Text = "", PlaceholderText = "theme name...",
        PlaceholderColor3 = self.Theme.TextMuted, Font = Enum.Font.Gotham, TextSize = 13,
        TextColor3 = self.Theme.TextPrimary, BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3, ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, -120, 0, 26),
        Position = UDim2.new(0, 14, 0.5, -13), Parent = saveRow,
    })
    Corner(8, nameBox)
    Create("UIPadding", {
        PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = nameBox,
    })

    local saveBtn = Create("TextButton", {
        Text = "Save As", Font = Enum.Font.GothamBold, TextSize = 12,
        TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = self.Theme.Accent,
        BackgroundTransparency = 0.2, AutoButtonColor = false,
        Size = UDim2.fromOffset(100, 26),
        Position = UDim2.new(1, -114, 0.5, -13), Parent = saveRow,
    })
    Corner(8, saveBtn)
    BindTap(saveBtn, function()
        local name = nameBox.Text
        if name == "" then
            LucidUI:Notify({
                Title = "Invalid", Message = "Enter a theme name",
                Accent = Color3.fromRGB(255, 80, 80),
            })
            return
        end
        self:SaveCustomTheme(name)
        nameBox.Text = ""
    end, { MoveThreshold = 8 })

    self:_registerTheme(function(t)
        for _, r in ipairs(editorRows) do r.BackgroundColor3 = t.Surface end
        saveRow.BackgroundColor3 = t.Surface
        nameBox.BackgroundColor3 = t.Background
        nameBox.TextColor3 = t.TextPrimary
        saveBtn.BackgroundColor3 = t.Accent
    end)
end

function LucidUI.Window:_buildSavedThemesSettings()
    self:_addSettingSection("Saved Themes")

    local savedRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
        ClipsDescendants = true,
    })
    Corner(10, savedRow)
    self:_addSettingFrame(savedRow)

    local savedHeader = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 40), Parent = savedRow,
    })
    Create("TextLabel", {
        Text = "Saved Themes", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -100, 1, 0),
        Parent = savedHeader,
    })
    local savedArrow = Create("TextLabel", {
        Text = "v", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0), Size = UDim2.fromOffset(20, 40),
        Parent = savedHeader,
    })

    local savedList = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0), Position = UDim2.fromOffset(10, 40),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = savedRow,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = savedList,
    })

    local savedExpanded = false
    local savedRowFrames = {}

    local function updateListSize()
        local h = 0
        for _, f in ipairs(savedRowFrames) do
            h = h + f.Size.Y.Offset + 4
        end
        if h > 0 then h = h - 4 end
        h = h + 8

        if savedExpanded then
            Tween(savedList, 0.22, { Size = UDim2.new(1, -20, 0, h) }, Enum.EasingStyle.Quart):Play()
            Tween(savedRow, 0.22, { Size = UDim2.new(1, 0, 0, 40 + h + 8) }, Enum.EasingStyle.Quart):Play()
        end
    end

    local function rebuildSaved()
        for _, f in ipairs(savedRowFrames) do
            if f and f.Parent then f:Destroy() end
        end
        savedRowFrames = {}

        local names = Compat.listThemes()
        if #names == 0 then
            local empty = Create("TextLabel", {
                Text = "No saved themes yet",
                Font = Enum.Font.Gotham, TextSize = 12,
                TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 32),
                LayoutOrder = 1, Parent = savedList,
            })
            table.insert(savedRowFrames, empty)
            updateListSize()
            return
        end

        for i, name in ipairs(names) do
            local rowWrap = Create("Frame", {
                Size = UDim2.new(1, 0, 0, 32),
                BackgroundColor3 = self.Theme.Background,
                BackgroundTransparency = 0.5,
                LayoutOrder = i,
                Parent = savedList,
            })
            Corner(8, rowWrap)
            table.insert(savedRowFrames, rowWrap)

            local nameBtn = Create("TextButton", {
                Text = name,
                Font = Enum.Font.GothamMedium, TextSize = 13,
                TextColor3 = self.Theme.TextPrimary,
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Size = UDim2.new(1, -36, 1, 0),
                Position = UDim2.fromOffset(10, 0),
                ZIndex = 3, Parent = rowWrap,
            })

            local delBtn = Create("TextButton", {
                Text = "x",
                Font = Enum.Font.GothamBold, TextSize = 14,
                TextColor3 = Color3.fromRGB(255, 100, 100),
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Size = UDim2.fromOffset(28, 32),
                Position = UDim2.new(1, -32, 0, 0),
                ZIndex = 3, Parent = rowWrap,
            })

            local themeName = name
            BindTap(nameBtn, function()
                savedExpanded = false
                Tween(savedList, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
                Tween(savedRow, 0.22, { Size = UDim2.new(1, 0, 0, 40) }):Play()
                Tween(savedArrow, 0.2, { Rotation = 0 }):Play()
                self:LoadCustomTheme(themeName)
                if self._refreshSwatches then pcall(self._refreshSwatches) end
            end)

            BindTap(delBtn, function()
                Compat.delete("LucidUI/Themes/" .. themeName .. ".json")
                if self.ThemeName == themeName then self:SetTheme("Default") end
                rebuildSaved()
                LucidUI:Notify({ Title = "Deleted", Message = themeName })
            end, { MoveThreshold = 8 })

            nameBtn.MouseEnter:Connect(function()
                local t = self.Theme
                Tween(rowWrap, 0.12, { BackgroundColor3 = t.Accent, BackgroundTransparency = 0.3 }):Play()
            end)
            nameBtn.MouseLeave:Connect(function()
                local t = self.Theme
                Tween(rowWrap, 0.12, { BackgroundColor3 = t.Background, BackgroundTransparency = 0.5 }):Play()
            end)
        end

        updateListSize()
    end

    self._savedThemeSlotsRefresh = rebuildSaved

    BindTap(savedHeader, function()
        savedExpanded = not savedExpanded
        rebuildSaved()
        Tween(savedArrow, 0.2, { Rotation = savedExpanded and 180 or 0 }):Play()
    end)

    self:_registerTheme(function(t)
        savedRow.BackgroundColor3 = t.Surface
        savedArrow.TextColor3 = t.TextMuted
        for _, f in ipairs(savedRowFrames) do
            if f:IsA("Frame") then
                f.BackgroundColor3 = t.Background
            elseif f:IsA("TextLabel") then
                f.TextColor3 = t.TextMuted
            end
        end
    end)
end

-- ============================================================
-- Module: 07_settings_b.lua
-- ============================================================
--[[
    Settings B — background image, keybinds, configs, about,
    BuildSettingsPanel.

    Accent detection:
      AutoDetectAccent samples the image on a center-weighted grid,
      filters out transparent / near-black / near-white / desaturated
      pixels, buckets hues into 36 bins, smooths the histogram with a
      triangular kernel, picks the peak, and averages the actual pixels
      in the winning bin ± 1. Then it boosts saturation, clamps
      brightness, and runs a WCAG contrast pass against the current
      theme background — nudging the value channel up or down until
      the accent reaches a 3:1 ratio.

    Click handling:
      Every click goes through BindTap (from 01b_polish.lua). The
      image-transparency slider keeps InputBegan/InputChanged because
      drag IS its interaction model.

    Keybind capture:
      The pill-toggle keybind row uses a stateful listener. While
      capturing, LucidUI._keyListening is true so the window's global
      keybind handler ignores keystrokes.
]]

-- ============================================================
-- Contrast helpers (mirrors 07_settings_a.lua — the library keeps
-- these local to each file rather than threading them through the
-- module boundary)
-- ============================================================
local function relLuminance(c)
    local function lin(x)
        if x <= 0.03928 then return x / 12.92 end
        return ((x + 0.055) / 1.055) ^ 2.4
    end
    return 0.2126 * lin(c.R) + 0.7152 * lin(c.G) + 0.0722 * lin(c.B)
end

local function contrastRatio(c1, c2)
    local l1, l2 = relLuminance(c1), relLuminance(c2)
    if l1 < l2 then l1, l2 = l2, l1 end
    return (l1 + 0.05) / (l2 + 0.05)
end

function LucidUI.Window:_buildBackgroundSettings()
    self:_addSettingSection("Background Image")

    if self._bgTransparency == nil then self._bgTransparency = 0.10 end

    local urlRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
    })
    Corner(10, urlRow)
    self:_addSettingFrame(urlRow)

    Create("TextLabel", {
        Text = "Image URL", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -180, 1, 0), Parent = urlRow,
    })

    local urlBox = Create("TextBox", {
        Text = "", PlaceholderText = "asset id or https://...",
        PlaceholderColor3 = self.Theme.TextMuted, Font = Enum.Font.Gotham, TextSize = 11,
        TextColor3 = self.Theme.TextPrimary, BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3, ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.fromOffset(140, 26), Position = UDim2.new(1, -154, 0.5, -13), Parent = urlRow,
    })
    Corner(8, urlBox)
    Create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = urlBox })

    local actionRow = Create("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 36) })
    self:_addSettingFrame(actionRow)
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), Parent = actionRow,
    })

    local function mkBtn(text, color, cb)
        local b = Create("TextButton", {
            Text = text, Font = Enum.Font.GothamBold, TextSize = 11,
            TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = color,
            BackgroundTransparency = 0.2, AutoButtonColor = false,
            Size = UDim2.new(0.33, -4, 1, 0), Parent = actionRow,
        })
        Corner(8, b)
        BindTap(b, cb, { MoveThreshold = 8 })
        return b
    end

    mkBtn("Apply", self.Theme.Accent, function()
        local url = urlBox.Text
        if url == "" then return end
        self:SetBackgroundImage(url)
    end)

    mkBtn("Auto Accent", self.Theme.Surface, function()
        local url = urlBox.Text
        if url == "" then
            LucidUI:Notify({ Title = "No URL", Message = "Paste a URL first", Accent = Color3.fromRGB(255,80,80) })
            return
        end
        LucidUI:Notify({ Title = "Analyzing...", Message = "Sampling image pixels", Duration = 3 })
        task.spawn(function()
            local accent = self:AutoDetectAccent(url)
            if accent then
                self:SetAccent(accent)
                LucidUI:Notify({ Title = "Accent Detected",
                    Message = string.format("RGB(%d,%d,%d)",
                        math.floor(accent.R*255), math.floor(accent.G*255), math.floor(accent.B*255)) })
            else
                LucidUI:Notify({ Title = "Detection Failed", Message = "Check F9 for details", Accent = Color3.fromRGB(255,80,80) })
            end
        end)
    end)

    mkBtn("Clear", Color3.fromRGB(220, 60, 60), function()
        self:SetBackgroundImage(nil)
        urlBox.Text = ""
    end)

    local transRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 54),
    })
    Corner(10, transRow)
    self:_addSettingFrame(transRow)

    Create("TextLabel", {
        Text = "Image Transparency", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 6), Size = UDim2.new(1, -28, 0, 18), Parent = transRow,
    })

    local transValue = Create("TextLabel", {
        Text = string.format("%.2f", self._bgTransparency),
        Font = Enum.Font.GothamBold, TextSize = 13,
        TextColor3 = self.Theme.Accent, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Position = UDim2.fromOffset(14, 6), Size = UDim2.new(1, -28, 0, 18), Parent = transRow,
    })

    local transTrack = Create("Frame", {
        Size = UDim2.new(1, -28, 0, 4), Position = UDim2.new(0, 14, 1, -16),
        BackgroundColor3 = self.Theme.SliderTrack, BorderSizePixel = 0, Parent = transRow,
    })
    Corner(2, transTrack)

    local transFill = Create("Frame", {
        Size = UDim2.new(self._bgTransparency, 0, 1, 0),
        BackgroundColor3 = self.Theme.Accent, BorderSizePixel = 0, Parent = transTrack,
    })
    Corner(2, transFill)

    local transHandle = Create("Frame", {
        Size = UDim2.fromOffset(18, 18), AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(self._bgTransparency, 0, 0.5, 0),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, Parent = transTrack,
    })
    Corner(9, transHandle)

    local transDrag = Create("TextButton", {
        Text = "", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Parent = transTrack,
    })

    local active = false
    local function setTrans(input)
        local rel = math.clamp((input.Position.X - transTrack.AbsolutePosition.X) / transTrack.AbsoluteSize.X, 0, 1)
        self._bgTransparency = rel
        transFill.Size = UDim2.new(rel, 0, 1, 0)
        transHandle.Position = UDim2.new(rel, 0, 0.5, 0)
        transValue.Text = string.format("%.2f", rel)
        if self._bgImage and self._bgImage.Visible then
            self._bgImage.ImageTransparency = rel
        end
    end
    transDrag.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            active = true
            setTrans(input)
        end
    end)
    table.insert(self._conns, UserInputService.InputChanged:Connect(function(input)
        if not active then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then setTrans(input) end
    end))
    table.insert(self._conns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then active = false end
    end))

    local note = Create("TextLabel", {
        Text = "Accepts asset IDs (12345678), rbxassetid:// URLs, or https:// image links.\nDirect image links work best from i.imgur.com or similar hosts.",
        Font = Enum.Font.Gotham, TextSize = 11,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left, TextWrapped = true,
        Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    })
    self:_addSettingFrame(note)

    self:_registerTheme(function(t)
        urlRow.BackgroundColor3 = t.Surface
        urlBox.BackgroundColor3 = t.Background
        urlBox.TextColor3 = t.TextPrimary
        transRow.BackgroundColor3 = t.Surface
        transValue.TextColor3 = t.Accent
        transTrack.BackgroundColor3 = t.SliderTrack
        transFill.BackgroundColor3 = t.Accent
        note.TextColor3 = t.TextMuted
    end)
end

function LucidUI.Window:SetBackgroundImage(url)
    if not self._bgImage then return end
    if not url or url == "" then
        Tween(self._bgImage, 0.2, { ImageTransparency = 1 }):Play()
        task.delay(0.25, function()
            if self._bgImage then self._bgImage.Visible = false end
            if self.Main then self.Main.BackgroundTransparency = self.Theme.BackgroundTrans end
        end)
        self._backgroundUrl = nil
        return
    end
    self._backgroundUrl = url
    if url:match("^https?://") then
        local ok = self:_downloadAndLoadImage(url)
        if not ok then
            LucidUI:Notify({ Title = "Download Failed", Message = "Check F9 for details", Accent = Color3.fromRGB(255,80,80) })
        end
        return
    end
    local imageId = url
    if not url:match("^rbxasset") then
        local num = url:match("(%d+)")
        if not num then
            LucidUI:Notify({ Title = "Invalid URL", Message = "Use asset ID or https link", Accent = Color3.fromRGB(255,80,80) })
            return
        end
        imageId = "rbxassetid://" .. num
    end
    self._bgImage.Image = imageId
    self._bgImage.Visible = true
    self._bgImage.ImageTransparency = 1
    Tween(self._bgImage, 0.4, { ImageTransparency = self._bgTransparency or 0.10 }):Play()
    Tween(self.Main, 0.4, { BackgroundTransparency = 0.65 }):Play()
end

function LucidUI.Window:_downloadAndLoadImage(url)
    print("[LucidUI] Downloading:", url)
    if not Compat.hasCustomAsset() then
        print("[LucidUI] FAIL: getcustomasset not available")
        return false
    end
    if not Compat.hasFS() then
        print("[LucidUI] FAIL: writefile not available")
        return false
    end
    local ext = url:match("%.(%w+)%?") or url:match("%.(%w+)$") or "png"
    ext = ext:lower()
    if ext ~= "png" and ext ~= "jpg" and ext ~= "jpeg" then ext = "png" end
    Compat.ensureFolders()
    local filename = "LucidUI/bg_" .. tostring(os.time()) .. "." .. ext
    local ok, data = pcall(function() return game:HttpGet(url, true) end)
    if not ok or not data or #data == 0 then
        print("[LucidUI] FAIL: HTTP download returned empty")
        return false
    end
    print("[LucidUI] Downloaded", #data, "bytes")
    if not Compat.write(filename, data) then
        print("[LucidUI] FAIL: writefile")
        return false
    end
    local assetOk, asset = pcall(getcustomasset, filename)
    if not assetOk or not asset then
        print("[LucidUI] FAIL: getcustomasset")
        return false
    end
    print("[LucidUI] Success")
    self._bgImage.Image = asset
    self._bgImage.Visible = true
    self._bgImage.ImageTransparency = 1
    Tween(self._bgImage, 0.4, { ImageTransparency = self._bgTransparency or 0.10 }):Play()
    Tween(self.Main, 0.4, { BackgroundTransparency = 0.65 }):Play()
    return true
end

-- ============================================================
-- Improved auto-accent: center-weighted hue analysis with
-- saturation-squared scoring and WCAG contrast enforcement.
--
-- Pipeline:
--   1. Resolve URL → EditableImage
--   2. Sample on a 60×60 grid
--   3. Per-pixel filter: alpha, brightness bounds, saturation floor
--   4. Score = saturation² × centerWeight
--   5. Hue histogram (36 bins) with triangular kernel over ±2
--   6. Peak bin → average actual pixels from peak ± 1 bins
--   7. HSV boost: saturation × 1.4, value clamped to [0.65, 0.92]
--   8. Contrast pass: nudge value until accent hits 3:1 against theme.Background
-- ============================================================
function LucidUI.Window:AutoDetectAccent(url, opts)
    opts = opts or {}

    local gridN       = opts.Grid          or 60
    local minSat      = opts.MinSat        or 0.18
    local minVal      = opts.MinVal        or 0.10
    local maxVal      = opts.MaxVal        or 0.95
    local minAlpha    = opts.MinAlpha      or 0.30
    local satBoost    = opts.SatBoost      or 1.4
    local valFloor    = opts.ValueFloor    or 0.65
    local valCeil     = opts.ValueCeil     or 0.92
    local targetRatio = opts.ContrastRatio or 3.0

    -- 1. Resolve to asset id
    local imageId = url
    if url:match("^https?://") then
        print("[LucidUI] AutoAccent: downloading image first")
        local ok = self:_downloadAndLoadImage(url)
        if not ok then
            print("[LucidUI] AutoAccent: download failed")
            return nil
        end
        imageId = self._bgImage.Image
    elseif not imageId:match("^rbxasset") then
        local num = imageId:match("(%d+)")
        if num then imageId = "rbxassetid://" .. num end
    end

    local AssetService = game:GetService("AssetService")
    if not AssetService or not AssetService.CreateEditableImageAsync then
        print("[LucidUI] AutoAccent: CreateEditableImageAsync unavailable")
        return nil
    end

    local ok, img = pcall(function()
        return AssetService:CreateEditableImageAsync(imageId)
    end)
    if not ok or not img then
        print("[LucidUI] AutoAccent: CreateEditableImageAsync threw")
        return nil
    end

    -- 2. Wait for size
    local size
    for _ = 1, 60 do
        local ok2, s = pcall(function() return img.Size end)
        if ok2 and s and s.X > 2 and s.Y > 2 then
            size = s
            break
        end
        task.wait(0.05)
    end
    if not size then
        print("[LucidUI] AutoAccent: image never loaded")
        return nil
    end
    print("[LucidUI] AutoAccent: image", size.X .. "x" .. size.Y)

    -- 3. Sample
    local cx, cy = size.X / 2, size.Y / 2
    local maxDist = math.sqrt(cx * cx + cy * cy)
    local stepX = math.max(1, math.floor(size.X / gridN))
    local stepY = math.max(1, math.floor(size.Y / gridN))

    local samples = {}
    for y = 0, size.Y - 1, stepY do
        for x = 0, size.X - 1, stepX do
            local ok3, pixels = pcall(function()
                return img:ReadPixels(Vector2.new(x, y), Vector2.new(1, 1))
            end)
            if ok3 and pixels and #pixels >= 3 then
                local r, g, b = pixels[1], pixels[2], pixels[3]
                local a = (#pixels >= 4) and pixels[4] or 1

                if a >= minAlpha then
                    local c = Color3.new(r, g, b)
                    local h, s, v = Color3.toHSV(c)

                    if v > minVal and v < maxVal and s > minSat then
                        -- Center weight: 1.0 at center, 0.35 at edges.
                        local dx, dy = x - cx, y - cy
                        local dist = math.sqrt(dx * dx + dy * dy)
                        local centerWeight = 1.0 - (dist / maxDist) * 0.65

                        table.insert(samples, {
                            r = r, g = g, b = b,
                            h = h, s = s, v = v,
                            weight = (s * s) * centerWeight,
                        })
                    end
                end
            end
        end
    end

    if #samples == 0 then
        print("[LucidUI] AutoAccent: no valid saturated pixels")
        return nil
    end
    print("[LucidUI] AutoAccent: samples =", #samples)

    -- 4. Hue histogram with triangular kernel
    local BINS = 36
    local bins = {}
    for i = 1, BINS do bins[i] = { weight = 0, rSum = 0, gSum = 0, bSum = 0 } end

    for _, s in ipairs(samples) do
        local bin = math.floor(s.h * BINS) + 1
        if bin < 1 then bin = 1 end
        if bin > BINS then bin = BINS end
        bins[bin].weight = bins[bin].weight + s.weight
        bins[bin].rSum   = bins[bin].rSum + s.r * s.weight
        bins[bin].gSum   = bins[bin].gSum + s.g * s.weight
        bins[bin].bSum   = bins[bin].bSum + s.b * s.weight
    end

    -- Triangular smoothing over ±2 bins, wrapping around the hue wheel
    local smoothed = {}
    for i = 1, BINS do
        local w0 = bins[i].weight
        local wl1 = bins[((i - 2) % BINS) + 1].weight
        local wr1 = bins[(i % BINS) + 1].weight
        local wl2 = bins[((i - 3) % BINS) + 1].weight
        local wr2 = bins[((i + 1) % BINS) + 1].weight
        smoothed[i] = w0 + (wl1 + wr1) * 0.6 + (wl2 + wr2) * 0.25
    end

    local bestBin, bestScore = 1, -1
    for i = 1, BINS do
        if smoothed[i] > bestScore then
            bestScore = smoothed[i]
            bestBin = i
        end
    end

    -- 5. Representative color: average the raw samples in peak ± 1 bins
    local lo = ((bestBin - 2) % BINS) + 1
    local mi = bestBin
    local hi = (bestBin % BINS) + 1
    local accR, accG, accB, accW = 0, 0, 0, 0
    for _, s in ipairs(samples) do
        local bin = math.floor(s.h * BINS) + 1
        if bin < 1 then bin = 1 end
        if bin > BINS then bin = BINS end
        if bin == lo or bin == mi or bin == hi then
            accR = accR + s.r * s.weight
            accG = accG + s.g * s.weight
            accB = accB + s.b * s.weight
            accW = accW + s.weight
        end
    end
    if accW == 0 then
        print("[LucidUI] AutoAccent: peak neighbourhood empty")
        return nil
    end
    local avg = Color3.new(accR / accW, accG / accW, accB / accW)

    -- 6. HSV boost
    local h, s, v = Color3.toHSV(avg)
    s = math.min(s * satBoost, 1)
    v = math.clamp(v, valFloor, valCeil)
    local result = Color3.fromHSV(h, s, v)

    -- 7. Contrast pass against the current theme background
    local bg = (self.Theme and self.Theme.Background) or Color3.fromRGB(28, 28, 30)
    local ratio = contrastRatio(result, bg)
    print(string.format("[LucidUI] AutoAccent: pre-contrast ratio %.2f", ratio))

    local guard = 0
    while ratio < targetRatio and guard < 12 do
        guard = guard + 1
        local hh, ss, vv = Color3.toHSV(result)
        local bgLum = relLuminance(bg)

        -- Decide direction: darken against light backgrounds,
        -- lighten against dark ones.
        if bgLum > 0.45 then
            vv = vv - 0.06
        else
            vv = vv + 0.06
        end
        vv = math.clamp(vv, 0.15, 0.98)
        result = Color3.fromHSV(hh, ss, vv)
        ratio = contrastRatio(result, bg)

        -- If we've hit the value bounds and still failing, kill
        -- saturation and switch to pure white or black.
        if vv <= 0.15 or vv >= 0.98 then
            if bgLum > 0.45 then
                result = Color3.fromRGB(20, 20, 24)
            else
                result = Color3.fromRGB(240, 240, 245)
            end
            break
        end
    end

    local finalH, finalS, finalV = Color3.toHSV(result)
    print(string.format(
        "[LucidUI] AutoAccent: rgb(%d,%d,%d) hsv(%.2f,%.2f,%.2f) contrast %.2f",
        math.floor(result.R * 255), math.floor(result.G * 255), math.floor(result.B * 255),
        finalH, finalS, finalV, ratio
    ))

    return result
end

-- ============================================================
-- Keybinds — global hotkeys that work on desktop
-- ============================================================
function LucidUI.Window:_buildKeybindSettings()
    self:_addSettingSection("Keybinds")

    local row = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 44),
    })
    Corner(10, row)
    self:_addSettingFrame(row)

    Create("TextLabel", {
        Text = "Minimize to Pill",
        Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0),
        Size = UDim2.new(1, -120, 1, 0),
        Parent = row,
    })

    local keyBox = Create("TextButton", {
        Text = self.PillKeybind and self.PillKeybind.Name or "Home",
        Font = Enum.Font.GothamBold, TextSize = 12,
        TextColor3 = self.Theme.TextPrimary,
        BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3,
        AutoButtonColor = false,
        Size = UDim2.fromOffset(90, 26),
        Position = UDim2.new(1, -104, 0.5, -13),
        Parent = row,
    })
    Corner(8, keyBox)

    local listenConn = nil

    local function stopListening()
        if listenConn then listenConn:Disconnect() listenConn = nil end
        keyBox.Text = self.PillKeybind and self.PillKeybind.Name or "Home"
        keyBox.BackgroundColor3 = self.Theme.Background
        LucidUI._keyListening = false
        self._cancelKeybindListen = nil
    end

    self._cancelKeybindListen = stopListening

    local function startListening()
        if LucidUI._keyListening then return end
        LucidUI._keyListening = true
        keyBox.Text = "..."
        keyBox.BackgroundColor3 = self.Theme.Accent
        PlayUISound("click")

        listenConn = UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end
            if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
            if input.KeyCode == Enum.KeyCode.Escape then
                stopListening()
                return
            end
            self.PillKeybind = input.KeyCode
            self._configData["pill_keybind"] = input.KeyCode.Name
            stopListening()
            LucidUI:Notify({
                Title = "Keybind Set",
                Message = "Pill toggle: " .. input.KeyCode.Name,
            })
        end)
    end

    BindTap(keyBox, startListening)

    table.insert(self._conns, UserInputService.InputBegan:Connect(function(input, processed)
        if not LucidUI._keyListening then return end
        if listenConn == nil then return end
        if input.UserInputType == Enum.UserInputType.Touch
            or input.UserInputType == Enum.UserInputType.MouseButton1 then
            if not processed then stopListening() end
        end
    end))

    self:_registerTheme(function(t)
        row.BackgroundColor3 = t.Surface
        if not LucidUI._keyListening then
            keyBox.BackgroundColor3 = t.Background
            keyBox.TextColor3 = t.TextPrimary
        end
    end)
end

-- ============================================================
-- Config slots
-- ============================================================
function LucidUI.Window:_buildConfigSettings()
    self:_addSettingSection("Configs")

    local row = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
        ClipsDescendants = true,
    })
    Corner(10, row)
    self:_addSettingFrame(row)

    local headerBtn = Create("TextButton", {
        Text = "", BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 40), Parent = row,
    })
    Create("TextLabel", {
        Text = "Active Config", Font = Enum.Font.GothamMedium, TextSize = 14,
        TextColor3 = self.Theme.TextPrimary, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -100, 1, 0), Parent = headerBtn,
    })
    local slotLabel = Create("TextLabel", {
        Text = self._currentConfig, Font = Enum.Font.GothamMedium, TextSize = 13,
        TextColor3 = self.Theme.Accent, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Size = UDim2.new(1, -34, 1, 0), Parent = headerBtn,
    })
    local arrowLbl = Create("TextLabel", {
        Text = "v", Font = Enum.Font.GothamBold, TextSize = 14,
        TextColor3 = self.Theme.TextMuted, BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0), Size = UDim2.fromOffset(20, 40), Parent = headerBtn,
    })

    local list = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0), Position = UDim2.fromOffset(10, 40),
        BackgroundTransparency = 1, ClipsDescendants = true, Parent = row,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder, Parent = list,
    })

    local expanded = false
    local slotButtons = {}

    local function rebuildSlots()
        for _, b in ipairs(slotButtons) do b:Destroy() end
        slotButtons = {}
        local slots = Compat.listConfigs()
        for i, name in ipairs(slots) do
            local isDefault = (name == "default")
            local label = isDefault and (name .. "  (locked)") or name
            local opt = Create("TextButton", {
                Text = label, Font = Enum.Font.GothamMedium, TextSize = 13,
                TextColor3 = self.Theme.TextPrimary, BackgroundColor3 = self.Theme.Background,
                BackgroundTransparency = 0.5, AutoButtonColor = false,
                Size = UDim2.new(1, 0, 0, 32), LayoutOrder = i, Parent = list,
            })
            Corner(8, opt)
            local configName = name
            BindTap(opt, function()
                self._currentConfig = configName
                slotLabel.Text = configName
                expanded = false
                Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
                Tween(row, 0.22, { Size = UDim2.new(1, 0, 0, 40) }):Play()
                Tween(arrowLbl, 0.2, { Rotation = 0 }):Play()
                self:LoadConfig(configName)
            end)
            table.insert(slotButtons, opt)
        end
    end

    BindTap(headerBtn, function()
        expanded = not expanded
        local h = 0
        if expanded then rebuildSlots(); h = #slotButtons * 36 + 8 end
        Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, expanded and h or 0) }, Enum.EasingStyle.Quart):Play()
        Tween(row, 0.22, { Size = UDim2.new(1, 0, 0, expanded and (40 + h + 8) or 40) }, Enum.EasingStyle.Quart):Play()
        Tween(arrowLbl, 0.2, { Rotation = expanded and 180 or 0 }):Play()
    end)

    self._themeSlotsRefresh = rebuildSlots

    local newRow = Create("Frame", {
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = self.Theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
    })
    Corner(10, newRow)
    self:_addSettingFrame(newRow)
    local inputBox = Create("TextBox", {
        Text = "", PlaceholderText = "new config name...",
        PlaceholderColor3 = self.Theme.TextMuted, Font = Enum.Font.Gotham, TextSize = 13,
        TextColor3 = self.Theme.TextPrimary, BackgroundColor3 = self.Theme.Background,
        BackgroundTransparency = 0.3, ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, -110, 0, 26), Position = UDim2.new(0, 14, 0.5, -13), Parent = newRow,
    })
    Corner(8, inputBox)
    Create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = inputBox })
    local saveNewBtn = Create("TextButton", {
        Text = "Save As New", Font = Enum.Font.GothamBold, TextSize = 12,
        TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = self.Theme.Accent,
        BackgroundTransparency = 0.2, AutoButtonColor = false,
        Size = UDim2.fromOffset(90, 26), Position = UDim2.new(1, -104, 0.5, -13), Parent = newRow,
    })
    Corner(8, saveNewBtn)
    BindTap(saveNewBtn, function()
        local name = inputBox.Text
        if name == "" or name == "default" then
            LucidUI:Notify({ Title = "Invalid Name", Message = "Pick another name", Accent = Color3.fromRGB(255,80,80) })
            return
        end
        self:SaveConfig(name)
        inputBox.Text = ""
        rebuildSlots()
    end, { MoveThreshold = 8 })

    local actionRow = Create("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 36) })
    self:_addSettingFrame(actionRow)
    Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), Parent = actionRow,
    })

    local function mkBtn(label, color, cb)
        local b = Create("TextButton", {
            Text = label, Font = Enum.Font.GothamBold, TextSize = 12,
            TextColor3 = Color3.fromRGB(255, 255, 255), BackgroundColor3 = color,
            BackgroundTransparency = 0.2, AutoButtonColor = false,
            Size = UDim2.new(0.33, -4, 1, 0), Parent = actionRow,
        })
        Corner(8, b)
        BindTap(b, cb, { MoveThreshold = 8 })
        return b
    end

    mkBtn("Save", self.Theme.Accent, function()
        self:SaveConfig(self._currentConfig)
        rebuildSlots()
    end)
    mkBtn("Load", self.Theme.Surface, function()
        self:LoadConfig(self._currentConfig)
    end)
    mkBtn("Delete", Color3.fromRGB(220, 60, 60), function()
        if self._currentConfig == "default" then
            LucidUI:Notify({ Title = "Cannot Delete", Message = "Default is locked", Accent = Color3.fromRGB(255,80,80) })
            return
        end
        Compat.delete("LucidUI/Configs/" .. self._currentConfig .. ".json")
        self._currentConfig = "default"
        slotLabel.Text = "default"
        rebuildSlots()
    end)

    self:_registerTheme(function(t)
        row.BackgroundColor3 = t.Surface
        slotLabel.TextColor3 = t.Accent
        arrowLbl.TextColor3 = t.TextMuted
        newRow.BackgroundColor3 = t.Surface
        inputBox.BackgroundColor3 = t.Background
        inputBox.TextColor3 = t.TextPrimary
        saveNewBtn.BackgroundColor3 = t.Accent
        for _, b in ipairs(slotButtons) do
            b.BackgroundColor3 = t.Background
            b.TextColor3 = t.TextPrimary
        end
    end)
end

